                          <span className="font-black text-primary-dark dark:text-primary text-sm">R$ {Number(variant.price).toFixed(2)}</span>
                        </div>
                        <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1 shadow-sm">
                          {qty > 0 ? (
                            <>
                              <button onClick={() => removeFromCart(product.id, variant.id)} className="w-8 h-8 flex items-center justify-center text-neutral-400"><span className="material-symbols-outlined text-lg">remove</span></button>
                              <span className="w-6 text-center text-xs font-black">{qty}</span>
                              <button onClick={() => addToCart(product, variant.id)} className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-black"><span className="material-symbols-outlined text-lg font-black">add</span></button>
                            </>
