            <div className="mt-8">
              <p className="text-center opacity-60 italic text-[9px]">Obrigado pela preferência!</p>
            </div>
          </div>
        )}

        <div id="checkout-section" className="mt-12 space-y-4 mb-32 bg-white dark:bg-white/5 p-6 rounded-3xl border border-neutral-100 dark:border-white/5">
          <h2 className="text-xs font-black uppercase tracking-widest text-primary px-1">Finalizar Pedido</h2>
          <div className="space-y-2">
            <input 
              ref={nameInputRef}
              value={clientName} 
              onChange={(e) => {
                setClientName(e.target.value);
                if (e.target.value.trim().length >= 3) setShowNameError(false);
              }} 
              placeholder="Digite seu nome..." 
              className={`w-full p-4 rounded-2xl border bg-neutral-50 dark:bg-black/20 text-sm font-bold outline-none transition-all ${showNameError ? 'border-red-500 ring-2 ring-red-500/10' : 'border-neutral-100 dark:border-white/5 focus:ring-2 focus:ring-primary/20'}`} 
            />
            {showNameError && (
              <p className="text-[10px] text-red-500 font-black uppercase tracking-widest px-1 animate-pulse italic">
                ⚠️ Nome é obrigatório para continuar
              </p>
            )}
          </div>
          <div className="grid grid-cols-2 gap-3">
            <button onClick={() => setPaymentMethod('Pix')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Pix' ? 'bg-primary/20 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Pix</button>
            <button onClick={() => setPaymentMethod('Dinheiro')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Dinheiro' ? 'bg-primary/20 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Dinheiro</button>
          </div>

          <p className="text-[9px] text-center text-neutral-400 font-bold uppercase tracking-wider mt-4">
            ⚠️ Pedido sujeito a alteração por disponibilidade de estoque.
          </p>
        </div>
      </main>

      <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-background-light dark:from-background-dark via-background-light/80 dark:via-background-dark/80 to-transparent">
        <button 
          onClick={handleConfirmOrder} 
          disabled={isButtonDisabled} 
          className={`w-full py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed' : 'bg-primary text-black shadow-primary/30'}`}
        >
          {isProcessing ? 'Enviando...' : 'Enviar pedido pelo WhatsApp'}
        </button>
      </div>
    </div>
  );
};

export default CatalogView;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw new Error(prodError.message);

      const hasSeededBefore = localStorage.getItem('has_seeded_v1') === 'true';

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.isActive ?? v.is_active ?? true,
            price: Number(v.price)
          }))
        }));

        const sorted = [...normalized].sort((a: any, b: any) => {
          const orderA = a.order_index ?? 999;
          const orderB = b.order_index ?? 999;
          if (orderA !== orderB) return orderA - orderB;
          return a.name.localeCompare(b.name);
        });

        setProducts(sorted);
        localStorage.setItem('cached_products', JSON.stringify(sorted));
      } else if (!hasSeededBefore) {
        setProducts(INITIAL_PRODUCTS);
        const seed = INITIAL_PRODUCTS.map((p, i) => ({
          ...p,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        await supabase.from('products').upsert(seed);
        localStorage.setItem('has_seeded_v1', 'true');
        localStorage.setItem('cached_products', JSON.stringify(INITIAL_PRODUCTS));
      } else {
        setProducts([]);
        localStorage.setItem('cached_products', JSON.stringify([]));
      }

      const { data: dbSettings, error: settingsError } = await supabase.from('settings').select('*');
      if (settingsError) throw new Error(settingsError.message);

      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err: any) {
      console.error("Erro ao buscar dados:", err.message);
      const cached = localStorage.getItem('cached_products');
      if (cached) setProducts(JSON.parse(cached));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    try {
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map(v => ({
          ...v,
          is_active: v.isActive
        })),
        is_active: product.isActive
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro ao salvar produto:", err);
      alert("Não foi possível salvar: " + (err.message || "Erro de conexão"));
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este produto?")) return;
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      const updatedProducts = products.filter(p => p.id !== id);
      setProducts(updatedProducts);
      localStorage.setItem('cached_products', JSON.stringify(updatedProducts));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err: any) {
      alert("Erro ao excluir do servidor: " + err.message);
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    const { error } = await supabase.from('products').update({ is_active: newStatus }).eq('id', id);
    if (error) {
      alert("Erro ao atualizar status: " + error.message);
      fetchData(); 
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...p, variants: updatedVariants } : p));
    const { error } = await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
    if (error) {
      alert("Erro ao atualizar variante: " + error.message);
      fetchData();
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const [movedItem] = newProducts.splice(index, 1);
    newProducts.splice(targetIndex, 0, movedItem);
    setProducts(newProducts);
    localStorage.setItem('cached_products', JSON.stringify(newProducts));
  };

  const handleUpdateWhatsapp = async (num: string) => { 
    setWhatsappNumber(num); 
    const { error } = await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' }); 
    if (error) alert("Erro ao salvar WhatsApp: " + error.message);
  };

  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); 
    const { error } = await supabase.from('settings').upsert({ key: 'categories', value: updated }, { onConflict: 'key' }); 
    if (error) alert("Erro ao salvar Marcas: " + error.message);
  };

  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); 
    const { error } = await supabase.from('settings').upsert({ key: 'presets', value: updated }, { onConflict: 'key' });
    if (error) alert("Erro ao salvar Presets: " + error.message);
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Isso apagará todas as suas edições e restaurará os produtos originais. Confirmar?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      localStorage.removeItem('has_seeded_v1');
      await fetchData();
    } catch (e: any) {
      alert("Erro ao restaurar: " + e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome para continuar.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;

    if (receiptUrl) {
      message += `\n\n🖼️ *Ver Comprovante:* ${receiptUrl}`;
    }

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-primary/30">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-xs uppercase tracking-widest text-primary animate-pulse">Sincronizando Banco de Dados...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} 
              onToggleVariantStatus={toggleVariantStatus}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('Gerando Cupom...');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);
  const nameInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isButtonDisabled = cart.length === 0 || isProcessing;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;

    if (!isNameValid) {
      setShowNameError(true);
      alert('⚠️ Por favor, informe seu nome (mínimo 3 letras) para que possamos identificar seu pedido.');
      nameInputRef.current?.focus();
      nameInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Gerando Comprovante...');
    setShowNameError(false);

    try {
      let receiptUrl = undefined;

      if (receiptRef.current) {
        // Captura o comprovante como imagem
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        setProcessingStatus('Enviando Comprovante...');

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], fileName, { type: 'image/png' });

          // Upload para o Supabase Storage (reaproveitando o bucket 'product-images')
          const { error: uploadError } = await supabase.storage
            .from('product-images')
            .upload(fileName, file);

          if (!uploadError) {
            const { data } = supabase.storage
              .from('product-images')
              .getPublicUrl(fileName);
            receiptUrl = data.publicUrl;
          } else {
            console.error("Erro no upload do comprovante:", uploadError.message);
          }
        }
      }

      onSendWhatsApp(paymentMethod, receiptUrl);
    } catch (err) {
      console.error("Erro ao processar pedido:", err);
      onSendWhatsApp(paymentMethod);
    } finally {
      setIsProcessing(false);
    }
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center text-white p-6 text-center animate-in fade-in">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <p className="font-black text-lg uppercase tracking-widest mb-2">{processingStatus}</p>
          <p className="text-sm opacity-60">Redirecionando para o WhatsApp em instantes...</p>
        </div>
      )}

      <header className="sticky top-0 z-50 w-full bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md shadow-sm border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 flex items-center justify-center rounded-2xl bg-primary text-black shadow-lg shadow-primary/20">
            <span className="material-symbols-outlined font-black">storefront</span>
          </div>
          <div>
            <h1 className="font-black text-sm uppercase tracking-tighter">Doce Mania</h1>
            <p className="text-[9px] font-bold text-primary uppercase leading-none italic">Qualidade & Sabor</p>
          </div>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="flex-1 pb-64 px-4 pt-6">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-6 -mx-4 px-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20 scale-105' : 'bg-white dark:bg-white/5 border border-neutral-100 dark:border-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-6">
          {filteredProducts.map(product => {
            const variantsArray = Array.isArray(product.variants) ? product.variants : [];
            const activeVariants = variantsArray.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="rounded-3xl bg-white dark:bg-white/5 p-4 border border-neutral-100 dark:border-white/5 shadow-sm hover:shadow-md transition-shadow animate-in slide-in-from-bottom-4">
                <div className="aspect-[4/3] w-full overflow-hidden rounded-2xl bg-neutral-50 dark:bg-black/20 mb-4 border border-neutral-100 dark:border-white/5 flex items-center justify-center relative">
                  <img 
                    src={product.image} 
                    alt={product.name}
                    className="h-full w-full object-cover transition-transform hover:scale-105 duration-700"
                    onError={(e) => { 
                      e.currentTarget.style.display = 'none';
                      const parent = e.currentTarget.parentElement;
                      if (parent) {
                        const fallback = document.createElement('div');
                        fallback.className = 'flex flex-col items-center justify-center text-neutral-300 dark:text-neutral-700 p-8 text-center';
                        fallback.innerHTML = '<span class="material-symbols-outlined text-4xl mb-2">image_not_supported</span><p class="text-[8px] font-black uppercase tracking-widest">Imagem indisponível</p>';
                        parent.appendChild(fallback);
                      }
                    }}
                  />
                </div>
                <div className="mb-4 px-1">
                  <h3 className="font-black text-base leading-tight">{product.name}</h3>
                  {product.description && <p className="text-[11px] text-neutral-400 mt-1 line-clamp-2">{product.description}</p>}
                </div>

                <div className="space-y-3">
                  {activeVariants.map((variant) => {
                    const qty = getQuantity(product.id, variant.id);
                    return (
                      <div key={variant.id} className="flex items-center justify-between p-3 rounded-2xl bg-neutral-50 dark:bg-black/20 border border-transparent hover:border-primary/20 transition-all">
                        <div className="flex flex-col">
                          {activeVariants.length > 1 && <span className="text-[9px] text-neutral-400 uppercase font-black tracking-widest mb-0.5">{variant.name}</span>}
                          <span className="font-black text-primary-dark dark:text-primary text-sm">R$ {Number(variant.price).toFixed(2)}</span>
                        </div>
                        <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1 shadow-sm">
                          {qty > 0 ? (
                            <>
                              <button onClick={() => removeFromCart(product.id, variant.id)} className="w-8 h-8 flex items-center justify-center text-neutral-400"><span className="material-symbols-outlined text-lg">remove</span></button>
                              <span className="w-6 text-center text-xs font-black">{qty}</span>
                              <button onClick={() => addToCart(product, variant.id)} className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-black"><span className="material-symbols-outlined text-lg font-black">add</span></button>
                            </>
                          ) : (
                            <button 
                              onClick={() => addToCart(product, variant.id)} 
                              className="px-5 py-2 text-[10px] font-black uppercase tracking-widest text-primary-dark dark:text-primary hover:bg-primary/5 rounded-lg transition-colors"
                            >
                              Adicionar
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            );
          })}
        </div>

