export default CatalogView;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('Gerando Cupom...');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);
  const nameInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isButtonDisabled = cart.length === 0 || isProcessing;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;

    if (!isNameValid) {
      setShowNameError(true);
      alert('⚠️ Por favor, informe seu nome (mínimo 3 letras) para que possamos identificar seu pedido.');
      nameInputRef.current?.focus();
      nameInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Gerando Comprovante...');
    setShowNameError(false);

    try {
      let receiptUrl = undefined;

      if (receiptRef.current) {
        // Captura o comprovante como imagem
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        setProcessingStatus('Enviando Comprovante...');

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const timestamp = Date.now();
          const fileName = `receipts/pedido-${timestamp}.png`;
          // Compatibilidade mobile: criar File explicitamente
          const file = new File([blob], `pedido-${timestamp}.png`, { type: 'image/png' });

          const { error: uploadError } = await supabase.storage
            .from('product-images')
            .upload(fileName, file, { cacheControl: '3600', upsert: false });

          if (!uploadError) {
            const { data } = supabase.storage
              .from('product-images')
              .getPublicUrl(fileName);
            receiptUrl = data.publicUrl;
          } else {
            console.error("Erro no upload:", uploadError.message);
            if (uploadError.message.includes('not found')) {
              alert("⚠️ Aviso Administrativo: O bucket 'product-images' não foi encontrado no Supabase. O pedido será enviado apenas por texto.");
            }
          }
        }
      }

      onSendWhatsApp(paymentMethod, receiptUrl);
    } catch (err) {
      console.error("Erro ao processar pedido:", err);
      onSendWhatsApp(paymentMethod);
    } finally {
      setIsProcessing(false);
    }
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col">
