import React, { useState } from 'react';
import { Product } from '../types';

interface AdminViewProps {
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  storageReady: boolean | 'error';
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
  onReorderProduct: (id: string, direction: 'up' | 'down') => void;
  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onResetToDefaults?: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  storageReady,
  onToggleStatus, 
  onToggleVariantStatus,
  onReorderProduct,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onResetToDefaults,
  onBack, 
  onLogout 
}) => {
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [tempPhone, setTempPhone] = useState(whatsappNumber);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const handleSavePhone = () => {
    const cleaned = tempPhone.replace(/\D/g, '');
    if (cleaned.length < 10) return;
    setWhatsappNumber(cleaned);
    setIsEditingPhone(false);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5">
            <span className="material-symbols-outlined">arrow_back</span>
          </button>
          <h1 className="font-bold">Administração</h1>
        </div>
        <button onClick={onLogout} className="text-red-500">
          <span className="material-symbols-outlined">logout</span>
        </button>
      </div>

      <div className="p-4 space-y-6">
        {/* Aviso de Storage se não estiver pronto */}
        {storageReady === 'error' && (
          <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 p-4 rounded-2xl flex gap-3 items-start animate-in fade-in slide-in-from-top-2">
            <span className="material-symbols-outlined text-amber-500">warning</span>
            <div className="flex-1">
              <h3 className="text-xs font-black uppercase text-amber-600 dark:text-amber-400 mb-1">Configuração Necessária</h3>
              <p className="text-[10px] text-amber-700 dark:text-amber-300 leading-relaxed">
                O envio de fotos (upload) não funcionará até que você crie um <b>Bucket Público</b> chamado <b>"product-images"</b> no seu painel do Supabase Storage.
              </p>
            </div>
          </div>
        )}

        {/* Configurações Rápidas */}
        <div className="bg-white dark:bg-white/5 p-4 rounded-2xl border shadow-sm space-y-4">
          <div className="flex gap-2">
            <button onClick={onOpenCategories} className="flex-1 p-3 bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all active:scale-95">
              <span className="material-symbols-outlined text-sm">category</span> Marcas
            </button>
            <button onClick={onOpenVariations} className="flex-1 p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all active:scale-95">
              <span className="material-symbols-outlined text-sm">list_alt</span> Presets
            </button>
            {onResetToDefaults && (
              <button onClick={onResetToDefaults} className="p-3 bg-yellow-50 dark:bg-yellow-900/20 text-yellow-600 dark:text-yellow-400 rounded-xl transition-all active:scale-95">
                <span className="material-symbols-outlined text-sm">refresh</span>
              </button>
            )}
          </div>

          {isEditingPhone ? (
            <div className="flex gap-2 animate-in fade-in slide-in-from-top-1">
              <input 
                value={tempPhone} 
                onChange={(e) => setTempPhone(e.target.value)}
                className="flex-1 px-4 py-2 rounded-xl border dark:bg-black/20 text-sm focus:ring-2 focus:ring-primary outline-none"
                placeholder="DDD + Número"
              />
              <button onClick={handleSavePhone} className="px-4 py-2 bg-primary text-black font-bold rounded-xl text-xs">Salvar</button>
            </div>
          ) : (
            <div className="flex items-center justify-between bg-neutral-50 dark:bg-black/20 p-3 rounded-xl border">
              <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-green-500 text-sm">whatsapp</span>
                <span className="text-sm font-bold">{whatsappNumber}</span>
              </div>
              <button onClick={() => setIsEditingPhone(true)} className="text-[10px] font-black uppercase text-primary tracking-wider">Trocar Número</button>
            </div>
          )}
        </div>

        {/* Lista de Produtos */}
        <div className="space-y-3">
          <h2 className="text-xs font-black uppercase tracking-widest text-neutral-400 px-1 italic">Gestão de Itens</h2>
          {products.map((product, idx) => (
            <div key={product.id} className={`bg-white dark:bg-white/5 rounded-2xl border transition-all ${!product.isActive ? 'opacity-50' : ''}`}>
              <div className="p-3 flex items-center gap-3">
                {/* Reordenação */}
                <div className="flex flex-col gap-1">
                  <button 
                    onClick={() => onReorderProduct(product.id, 'up')}
                    disabled={idx === 0}
                    className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-black/5 disabled:opacity-0"
                  >
                    <span className="material-symbols-outlined text-lg">keyboard_arrow_up</span>
                  </button>
                  <button 
                    onClick={() => onReorderProduct(product.id, 'down')}
                    disabled={idx === products.length - 1}
                    className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-black/5 disabled:opacity-0"
                  >
                    <span className="material-symbols-outlined text-lg">keyboard_arrow_down</span>
                  </button>
                </div>

                {/* Imagem */}
                <div 
                  onClick={() => toggleExpand(product.id)}
                  className="w-14 h-14 rounded-xl overflow-hidden bg-neutral-100 border shrink-0 cursor-pointer active:scale-95 transition-transform"
                >
                  <img 
                    src={product.image} 
                    className="w-full h-full object-cover" 
                    alt="" 
                    onError={(e) => { e.currentTarget.src = 'https://picsum.photos/100/100?grayscale'; }}
                  />
                </div>

                {/* Info */}
                <div 
                  onClick={() => toggleExpand(product.id)}
                  className="flex-1 min-w-0 cursor-pointer"
                >
                  <h3 className="text-sm font-bold truncate">{product.name}</h3>
                  <p className="text-[10px] text-primary uppercase font-black tracking-widest italic">{product.category}</p>
                </div>

                {/* Ações */}
                <div className="flex items-center gap-1">
                  <button 
                    onClick={() => onToggleStatus(product.id)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl transition-colors ${product.isActive ? 'text-green-500 hover:bg-green-50' : 'text-neutral-400 hover:bg-neutral-50'}`}
                    title="Ativar/Desativar"
                  >
                    <span className="material-symbols-outlined">{product.isActive ? 'visibility' : 'visibility_off'}</span>
                  </button>
                  <button 
                    onClick={() => onEditProduct(product)}
                    className="w-10 h-10 flex items-center justify-center rounded-xl text-blue-500 hover:bg-blue-50"
                    title="Editar"
                  >
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button 
                    onClick={() => onDeleteProduct(product.id)}
                    className="w-10 h-10 flex items-center justify-center rounded-xl text-red-500 hover:bg-red-50 active:scale-90 transition-transform"
                    title="Excluir"
                  >
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>

              {/* Variações Expansíveis */}
              {expandedId === product.id && (
                <div className="px-4 pb-4 pt-1 border-t border-dashed animate-in slide-in-from-top-2 duration-200">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-neutral-400 italic">Variações / Preços</span>
                    <span className="material-symbols-outlined text-neutral-300 text-sm">expand_less</span>
                  </div>
                  <div className="space-y-2">
                    {product.variants.map((v) => (
                      <div key={v.id} className="flex items-center justify-between bg-neutral-50 dark:bg-black/20 p-2.5 rounded-xl border border-transparent hover:border-primary/20 transition-all">
                        <div className="flex flex-col">
                          <span className="text-xs font-bold text-neutral-700 dark:text-neutral-300">{v.name}</span>
                          <span className="text-xs font-black text-primary-dark dark:text-primary">R$ {v.price.toFixed(2)}</span>
                        </div>
                        <button 
                          onClick={() => onToggleVariantStatus(product.id, v.id)}
                          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${v.isActive ? 'bg-green-500/10 text-green-600' : 'bg-neutral-500/10 text-neutral-400'}`}
                        >
                          <span className="material-symbols-outlined text-sm">{v.isActive ? 'check_circle' : 'cancel'}</span>
                          {v.isActive ? 'Ativo' : 'Off'}
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
          {products.length === 0 && (
            <div className="text-center py-20 bg-white/5 rounded-3xl border border-dashed border-neutral-200 dark:border-white/10">
              <span className="material-symbols-outlined text-5xl opacity-20 mb-2">inventory_2</span>
              <p className="text-sm font-bold opacity-40 uppercase tracking-widest">Nenhum produto cadastrado</p>
            </div>
          )}
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t p-4 flex items-center justify-around z-50">
        <button onClick={onBack} className="text-neutral-400 flex flex-col items-center gap-1 transition-all active:scale-90">
          <span className="material-symbols-outlined">storefront</span>
          <span className="text-[9px] font-bold uppercase">Catálogo</span>
        </button>
        <button 
          onClick={onAddProduct} 
          className="w-16 h-16 bg-primary text-black rounded-2xl shadow-xl shadow-primary/20 flex items-center justify-center -mt-12 transform hover:scale-105 active:scale-95 transition-all"
        >
          <span className="material-symbols-outlined text-4xl font-black">add</span>
        </button>
        <button onClick={onLogout} className="text-red-400 flex flex-col items-center gap-1 transition-all active:scale-90">
          <span className="material-symbols-outlined">logout</span>
          <span className="text-[9px] font-bold uppercase">Sair</span>
        </button>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, storageReady, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [imgStatus, setImgStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      if (productToEdit.image) setImgStatus('success');
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    setImgStatus('loading');
    if (raw.includes('<')) {
      const match = raw.match(/(?:src|href)\s*=\s*["']([^"']+)["']/i);
      if (match && match[1]) raw = match[1];
    }
    setImage(raw);
  };

  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Não foi possível acessar a câmera");
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);

        canvasRef.current.toBlob(async (blob) => {
          if (blob) {
            const file = new File([blob], `photo-${Date.now()}.jpg`, { type: 'image/jpeg' });
            await uploadFile(file);
          }
          stopCamera();
        }, 'image/jpeg', 0.8);
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const uploadFile = async (file: File) => {
    if (storageReady === 'error') {
      alert("⚠️ Erro de Configuração: O armazenamento (Storage) do Supabase não está pronto. Por favor, verifique o aviso na tela de administração.");
      return;
    }

    setIsUploading(true);
    setImgStatus('loading');
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file, { cacheControl: '3600', upsert: false });

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
      setImgStatus('success');
    } catch (error: any) {
      console.error('Upload falhou:', error.message);
      if (error.message.includes('not found')) {
        alert("❌ Erro: O 'bucket' de imagens não existe no Supabase. O administrador precisa criá-lo no painel do Supabase com o nome 'product-images'.");
      } else {
        alert('Upload falhou: ' + error.message);
      }
      setImgStatus('error');
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9),
      isActive: true
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) return alert('Precisa de pelo menos um preço.');
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, [field]: field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value } : v));
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleSubmit = async () => {
    if (!name.trim()) return alert('Nome obrigatório!');
    if (!category) return alert('Selecione uma marca!');

    setIsSaving(true);
    try {
      const productData: Product = {
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Doce+Mania',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.map(v => ({ ...v, name: v.name || 'Padrão' }))
      };
      await onSave(productData);
    } catch (err) {
      console.error(err);
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Item'}</h1>
      </div>

      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="absolute bottom-10 flex gap-6">
            <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/20 text-white flex items-center justify-center border-2 border-white">
              <span className="material-symbols-outlined">close</span>
            </button>
            <button onClick={capturePhoto} className="w-20 h-20 rounded-full bg-primary text-black flex items-center justify-center shadow-2xl scale-110">
              <span className="material-symbols-outlined text-4xl">photo_camera</span>
            </button>
          </div>
        </div>
      )}

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome do Item</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-xl border bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none" placeholder="Ex: Coca-Cola 350ml" />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full rounded-xl border bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Descrição</label>
            <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} className="w-full rounded-xl border bg-background-light dark:bg-black/20 p-3 text-sm outline-none" placeholder="Opcional..." />
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase tracking-widest text-primary flex items-center gap-2"><span className="material-symbols-outlined text-sm">image</span> Imagem</h2>

          <div className="space-y-3">
            <div className="relative">
              <label className="block text-[9px] text-neutral-400 font-bold uppercase mb-1">Link direto, tag HTML ou upload</label>
              <div className="flex gap-2">
                <input 
                  value={image} 
                  onChange={(e) => handleImageInput(e.target.value)} 
                  className={`flex-1 rounded-xl border bg-white dark:bg-black/40 p-3 text-xs outline-none focus:ring-2 transition-all ${imgStatus === 'error' ? 'border-red-500 focus:ring-red-200' : 'border-neutral-200 dark:border-white/10 focus:ring-primary/20'}`} 
                  placeholder="https://... ou cole o código HTML" 
                />
                {image && (
                  <button 
                    onClick={() => { setImage(''); setImgStatus('idle'); }} 
                    className="w-11 h-11 flex items-center justify-center bg-red-50 text-red-500 rounded-xl border border-red-100"
                  >
                    <span className="material-symbols-outlined text-sm">close</span>
                  </button>
                )}
              </div>
            </div>

            <div className="relative rounded-2xl border-2 border-dashed aspect-video bg-neutral-100 dark:bg-black/40 flex flex-col items-center justify-center overflow-hidden transition-all group">
              {imgStatus === 'loading' && (
                <div className="absolute inset-0 bg-white/50 dark:bg-black/50 backdrop-blur-sm z-10 flex items-center justify-center">
                  <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin"></div>
                </div>
              )}

              {image ? (
                <img 
                  src={image} 
                  className="w-full h-full object-contain" 
                  alt="Preview" 
                  onLoad={() => setImgStatus('success')}
                  onError={() => setImgStatus('error')} 
                />
              ) : (
                <div className="text-center opacity-30 px-6">
                  <span className="material-symbols-outlined text-4xl mb-2">image_search</span>
                  <p className="text-[10px] font-black uppercase tracking-widest">Sem imagem definida</p>
                  <p className="text-[8px] opacity-60 mt-1">Cole um link ou use os botões abaixo</p>
                </div>
              )}

              {imgStatus === 'error' && (
                <div className="absolute inset-0 bg-red-50/90 dark:bg-red-900/20 flex flex-col items-center justify-center p-4 text-center">
                  <span className="material-symbols-outlined text-red-500 mb-1">broken_image</span>
                  <p className="text-[9px] font-black text-red-600 uppercase">Link inválido ou inacessível</p>
                </div>
              )}

              <div className="absolute bottom-3 right-3 flex gap-2">
                <button 
                  type="button" 
                  onClick={startCamera} 
                  className="bg-blue-500 text-white w-10 h-10 rounded-xl shadow-lg active:scale-95 transition-transform flex items-center justify-center"
                  title="Tirar Foto"
                >
                  <span className="material-symbols-outlined text-xl">photo_camera</span>
                </button>
                <button 
                  type="button" 
                  onClick={() => fileInputRef.current?.click()} 
                  disabled={isUploading} 
                  className="bg-primary text-black w-10 h-10 rounded-xl shadow-lg active:scale-95 transition-transform flex items-center justify-center"
                  title="Upload de Arquivo"
                >
                  <span className="material-symbols-outlined text-xl">{isUploading ? 'sync' : 'upload'}</span>
                </button>
              </div>
            </div>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase tracking-widest text-primary">Preços</h2>
            <div className="flex gap-2">
              <button type="button" onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 px-2 py-1 rounded">Presets</button>
              <button type="button" onClick={handleAddVariant} className="text-[10px] font-black uppercase text-primary bg-primary/10 px-2 py-1 rounded">+ Novo</button>
            </div>
          </div>
          {showPresets && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border rounded-xl flex flex-wrap gap-2 animate-in fade-in zoom-in-95">
              {presets.map(p => <button type="button" key={p.id} onClick={() => handleApplyPreset(p)} className="px-3 py-1.5 bg-white dark:bg-neutral-800 border text-[10px] font-bold rounded-lg shadow-sm">{p.name}</button>)}
            </div>
          )}
          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className={`flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl border ${!v.isActive ? 'opacity-50' : ''}`}>
                <div className="flex gap-2 items-center">
                  <input value={v.name} onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} className="flex-1 bg-transparent border-none p-0 text-sm font-bold outline-none" placeholder="Ex: Unitário ou 500g" />
                  <div className="flex gap-1">
                    <button type="button" onClick={() => toggleVariantStatus(v.id)} className={`w-8 h-8 flex items-center justify-center rounded-lg ${v.isActive ? 'text-green-500' : 'text-neutral-400'}`}><span className="material-symbols-outlined text-sm">{v.isActive ? 'visibility' : 'visibility_off'}</span></button>
                    <button type="button" onClick={() => handleRemoveVariant(v.id)} className="w-8 h-8 flex items-center justify-center text-red-400"><span className="material-symbols-outlined text-sm">delete</span></button>
                  </div>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border">
                  <span className="text-neutral-500">R$</span>
                  <input type="number" step="0.01" value={v.price || ''} onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} className="w-full bg-transparent border-none p-0 outline-none" placeholder="0,00" />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button type="button" onClick={onCancel} disabled={isSaving} className="flex-1 py-4 font-bold rounded-2xl border active:scale-95 transition-transform">Cancelar</button>
        <button type="button" onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
          {isSaving ? (
            <>
              <span className="w-4 h-4 border-2 border-black border-t-transparent rounded-full animate-spin"></span>
              Gravando...
            </>
          ) : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [storageReady, setStorageReady] = useState<boolean | 'error'>(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const ensureStorageBucket = async () => {
    try {
      const { data: buckets } = await supabase.storage.listBuckets();
      const exists = buckets?.find(b => b.name === 'product-images');

      if (!exists) {
        const { error: createError } = await supabase.storage.createBucket('product-images', {
          public: true,
          fileSizeLimit: 5242880
        });
        setStorageReady(createError ? 'error' : true);
      } else {
        setStorageReady(true);
      }
    } catch (err) {
      setStorageReady('error');
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      await ensureStorageBucket();

      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('order_index', { ascending: true });

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        // Seed inicial se vazio
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err: any) {
      console.error("Erro no fetch:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    try {
      const payload = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map(v => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive
        })),
        is_active: product.isActive,
        order_index: product.order_index ?? products.length
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + err.message);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName})`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;

    if (receiptUrl) message += `\n\n🖼️ *Comprovante:* ${receiptUrl}`;

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); // Limpa carrinho após enviar
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-xs uppercase tracking-widest text-primary">Carregando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;
                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + 1} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: 1, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={storageReady}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ variants: updated.map(v => ({...v, is_active: v.isActive})) }).eq('id', pId);
                }
              }}
              onReorderProduct={async (id, dir) => {
                const idx = products.findIndex(p => p.id === id);
                const target = dir === 'up' ? idx - 1 : idx + 1;
                if (target < 0 || target >= products.length) return;
                const next = [...products];
                [next[idx], next[target]] = [next[target], next[idx]];
                const updated = next.map((p, i) => ({...p, order_index: i}));
                setProducts(updated);
                for (const p of updated) {
                  await supabase.from('products').update({ order_index: p.order_index }).eq('id', p.id);
                }
              }}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Excluir?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={storageReady}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Gerando Comprovante...');

    try {
      let receiptUrl = undefined;

      if (receiptRef.current) {
        // Pequeno delay para garantir renderização
        await new Promise(r => setTimeout(r, 300));

        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          allowTaint: true,
          backgroundColor: '#ffffff',
          logging: false,
          width: receiptRef.current.offsetWidth,
          height: receiptRef.current.offsetHeight
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          setProcessingStatus('Enviando para Nuvem...');
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          const { error: uploadError } = await supabase.storage
            .from('product-images')
            .upload(fileName, file);

          if (!uploadError) {
            const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
            receiptUrl = data.publicUrl;
          }
        }
      }
      onSendWhatsApp(paymentMethod, receiptUrl);
    } catch (err) {
      console.error("Erro no processamento:", err);
      onSendWhatsApp(paymentMethod); // Fallback
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  return (
    <div className="flex-1 w-full max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-lg uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 flex items-center justify-center rounded-2xl bg-primary text-black">
            <span className="material-symbols-outlined font-black">storefront</span>
          </div>
          <div>
            <h1 className="font-black text-sm uppercase">Doce Mania</h1>
            <p className="text-[9px] font-bold text-primary uppercase italic leading-none">Qualidade & Sabor</p>
          </div>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4 mb-2">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2 rounded-2xl text-xs font-black uppercase tracking-wider transition-all ${selectedCategory === cat ? 'bg-primary text-black scale-105' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-6">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 p-4 rounded-3xl border border-neutral-100 dark:border-white/5 shadow-sm">
                <div className="aspect-[4/3] rounded-2xl overflow-hidden bg-neutral-50 dark:bg-black/20 mb-4 border border-neutral-100 dark:border-white/5">
                  <img 
                    src={product.image} 
                    alt={product.name} 
                    className="w-full h-full object-cover"
                    onError={(e) => { e.currentTarget.src = 'https://picsum.photos/400/300?text=Doce+Mania'; }}
                  />
                </div>
                <div className="mb-4">
                  <h3 className="font-black text-base">{product.name}</h3>
                  {product.description && <p className="text-[11px] text-neutral-400 mt-1">{product.description}</p>}
                </div>
                <div className="space-y-2">
                  {activeVariants.map(v => {
                    const qty = getQuantity(product.id, v.id);
                    return (
                      <div key={v.id} className="flex items-center justify-between p-3 rounded-2xl bg-neutral-50 dark:bg-black/20">
                        <div className="flex flex-col">
                          {activeVariants.length > 1 && <span className="text-[9px] font-black uppercase text-neutral-400">{v.name}</span>}
                          <span className="font-black text-primary-dark dark:text-primary text-sm">R$ {v.price.toFixed(2)}</span>
                        </div>
                        <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1 shadow-sm">
                          {qty > 0 ? (
                            <>
                              <button onClick={() => removeFromCart(product.id, v.id)} className="w-8 h-8 flex items-center justify-center text-neutral-400"><span className="material-symbols-outlined text-lg">remove</span></button>
                              <span className="w-6 text-center text-xs font-black">{qty}</span>
                              <button onClick={() => addToCart(product, v.id)} className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-black"><span className="material-symbols-outlined text-lg font-black">add</span></button>
                            </>
                          ) : (
                            <button onClick={() => addToCart(product, v.id)} className="px-5 py-2 text-[10px] font-black uppercase text-primary-dark dark:text-primary">Adicionar</button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div className="mt-12 space-y-4">
            <div ref={receiptRef} className="p-6 bg-white text-black font-mono text-[11px] rounded shadow-xl border-t-8 border-primary">
              <h3 className="text-center font-black text-sm uppercase mb-1">DOCE MANIA</h3>
              <p className="text-center text-[9px] mb-4 opacity-60 italic">Sabor que transforma seu dia</p>
              <div className="border-b border-dashed pb-2 mb-4 flex justify-between opacity-60 text-[9px]">
                <span>{new Date().toLocaleDateString('pt-BR')}</span>
                <span>{new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <p className="mb-1 font-bold">CLIENTE: {clientName.toUpperCase() || '---'}</p>
              <p className="mb-4 font-bold">PAGAMENTO: {paymentMethod.toUpperCase()}</p>
              <div className="space-y-1 mb-4 border-b border-dashed pb-4">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between">
                    <span className="flex-1 pr-2">{item.quantity}x {item.productName.toUpperCase()}</span>
                    <span>R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-base">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-6 rounded-3xl border border-neutral-100 dark:border-white/5 space-y-4">
              <h2 className="text-xs font-black uppercase tracking-widest text-primary">Finalizar</h2>
              <input 
                value={clientName} 
                onChange={(e) => { setClientName(e.target.value); if(e.target.value.length >= 3) setShowNameError(false); }} 
                placeholder="Seu nome..." 
                className={`w-full p-4 rounded-2xl border bg-neutral-50 dark:bg-black/20 text-sm font-bold outline-none transition-all ${showNameError ? 'border-red-500 ring-2 ring-red-500/10' : 'border-neutral-100 dark:border-white/5 focus:ring-primary/20'}`}
              />
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setPaymentMethod('Pix')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase transition-all ${paymentMethod === 'Pix' ? 'bg-primary/20 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Pix</button>
                <button onClick={() => setPaymentMethod('Dinheiro')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase transition-all ${paymentMethod === 'Dinheiro' ? 'bg-primary/20 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Dinheiro</button>
              </div>
            </div>
          </div>
        )}
      </main>

      <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-white dark:from-background-dark via-white/80 to-transparent z-40">
        <button 
          onClick={handleConfirmOrder} 
          disabled={cart.length === 0 || isProcessing}
          className={`w-full py-5 rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl transition-all active:scale-95 ${cart.length === 0 || isProcessing ? 'bg-neutral-200 text-neutral-400' : 'bg-primary text-black'}`}
        >
          {isProcessing ? 'Enviando...' : 'Enviar pelo WhatsApp'}
        </button>
      </div>
    </div>
  );
};

export default CatalogView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, storageReady, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [imgStatus, setImgStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      if (productToEdit.image) setImgStatus('success');
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    if (raw.includes('<img')) {
      const match = raw.match(/src=["']([^"']+)["']/i);
      if (match) raw = match[1];
    }
    setImage(raw);
    setImgStatus(raw ? 'loading' : 'idle');
  };

  const uploadFile = async (file: File) => {
    if (storageReady === 'error') {
      alert("Armazenamento não disponível.");
      return;
    }

    setIsUploading(true);
    setImgStatus('loading');
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
      setImgStatus('success');
    } catch (error: any) {
      alert('Upload falhou: ' + error.message);
      setImgStatus('error');
    } finally { setIsUploading(false); }
  };

  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Sem acesso à câmera");
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        canvasRef.current.toBlob(async (blob) => {
          if (blob) await uploadFile(new File([blob], `foto.jpg`, { type: 'image/jpeg' }));
          stopCamera();
        }, 'image/jpeg', 0.8);
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    setShowCamera(false);
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Preencha os campos obrigatórios!');
    setIsSaving(true);
    try {
      const productData: Product = {
        id: productToEdit?.id || Date.now().toString(), 
        name: name.trim(), category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Item',
        isActive: productToEdit?.isActive ?? true,
        order_index: productToEdit?.order_index,
        variants: variants.map(v => ({ ...v, name: v.name || 'Padrão' }))
      };
      await onSave(productData);
    } finally { setIsSaving(false); }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar' : 'Novo Item'}</h1>
      </div>

      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="absolute bottom-10 flex gap-6">
            <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/20 text-white flex items-center justify-center border-2 border-white"><span className="material-symbols-outlined">close</span></button>
            <button onClick={capturePhoto} className="w-20 h-20 rounded-full bg-primary text-black flex items-center justify-center shadow-2xl scale-110"><span className="material-symbols-outlined text-4xl">photo_camera</span></button>
          </div>
        </div>
      )}

      <div className="px-4 pt-6 space-y-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-3xl border shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome</label>
            <input value={name} onChange={e => setName(e.target.value)} className="w-full rounded-2xl border dark:bg-black/20 p-4 text-sm font-bold outline-none" />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca</label>
            <select value={category} onChange={e => setCategory(e.target.value)} className="w-full rounded-2xl border dark:bg-black/20 p-4 text-sm font-bold outline-none">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Descrição</label>
            <textarea value={description} onChange={e => setDescription(e.target.value)} className="w-full rounded-2xl border dark:bg-black/20 p-4 text-sm outline-none" rows={2} />
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-3xl border shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase text-primary">Imagem</h2>
          <div className="space-y-3">
            <div className="flex gap-2">
              <input value={image} onChange={e => handleImageInput(e.target.value)} className="flex-1 rounded-2xl border dark:bg-black/20 p-4 text-xs outline-none" placeholder="Link ou Tag HTML" />
              <button onClick={() => { setImage(''); setImgStatus('idle'); }} className="w-12 h-12 flex items-center justify-center bg-red-50 text-red-500 rounded-2xl"><span className="material-symbols-outlined">close</span></button>
            </div>
            <div className="relative aspect-video rounded-3xl border-2 border-dashed bg-neutral-50 dark:bg-black/40 flex flex-col items-center justify-center overflow-hidden">
              {image ? (
                <img src={image} className="w-full h-full object-contain" alt="Preview" onLoad={() => setImgStatus('success')} onError={() => setImgStatus('error')} />
              ) : (
                <div className="text-center opacity-30"><span className="material-symbols-outlined text-4xl">image</span><p className="text-[10px] font-black">SEM IMAGEM</p></div>
              )}
              <div className="absolute bottom-3 right-3 flex gap-2">
                <button type="button" onClick={startCamera} className="w-10 h-10 bg-blue-500 text-white rounded-xl shadow-lg flex items-center justify-center"><span className="material-symbols-outlined">photo_camera</span></button>
                <button type="button" onClick={() => fileInputRef.current?.click()} className="w-10 h-10 bg-primary text-black rounded-xl shadow-lg flex items-center justify-center"><span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload'}</span></button>
              </div>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" onChange={e => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-3xl border shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase text-primary">Preços</h2>
            <button onClick={() => setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }])} className="text-[10px] font-black uppercase text-primary">+ Novo</button>
          </div>
          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="p-3 bg-neutral-50 dark:bg-black/20 rounded-2xl border">
                <div className="flex gap-2 items-center mb-2">
                  <input value={v.name} onChange={e => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} className="flex-1 bg-transparent border-none p-0 text-sm font-bold outline-none" placeholder="Unidade / Peso" />
                  <button onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="text-red-400"><span className="material-symbols-outlined text-sm">delete</span></button>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-2 rounded-xl border">
                  <span className="text-neutral-500">R$</span>
                  <input type="number" step="0.01" value={v.price} onChange={e => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} className="w-full bg-transparent border-none p-0 outline-none" />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-4 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t flex gap-3 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-4 font-bold rounded-2xl border">Cancelar</button>
        <button onClick={handleSubmit} disabled={isSaving} className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-lg">
          {isSaving ? 'Salvando...' : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [storageReady, setStorageReady] = useState<boolean | 'error'>(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const ensureStorageBucket = async () => {
    try {
      const { data: buckets } = await supabase.storage.listBuckets();
      const exists = buckets?.find(b => b.name === 'product-images');

      if (!exists) {
        const { error: createError } = await supabase.storage.createBucket('product-images', {
          public: true,
          fileSizeLimit: 5242880
        });
        setStorageReady(createError ? 'error' : true);
      } else {
        setStorageReady(true);
      }
    } catch (err) {
      setStorageReady('error');
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      await ensureStorageBucket();

      // Removido .order('order_index') para evitar erro caso a coluna não exista no Supabase
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));

        // Ordenação manual em memória: primeiro por order_index (se existir), depois por nome
        const sorted = [...normalized].sort((a, b) => {
          const oiA = a.order_index ?? 999;
          const oiB = b.order_index ?? 999;
          if (oiA !== oiB) return oiA - oiB;
          return a.name.localeCompare(b.name);
        });

        setProducts(sorted);
        localStorage.setItem('cached_products', JSON.stringify(sorted));
      } else {
        // Fallback para produtos iniciais se banco estiver vazio
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err: any) {
      console.error("Erro no fetch:", err.message);
      const cached = localStorage.getItem('cached_products');
      if (cached) setProducts(JSON.parse(cached));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    try {
      // Omitimos order_index do payload para evitar erros se a coluna não existir
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map(v => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive
        })),
        is_active: product.isActive
      };

      // Só adiciona order_index se estivermos editando e ele já existir, para evitar erro de coluna
      if (product.order_index !== undefined) {
        // Nota: Se a coluna realmente não existir, isso ainda pode falhar.
        // Se o erro persistir, o usuário deve criar a coluna 'order_index' (int4) no Supabase.
      }

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro ao salvar:", err);
      alert("Erro ao salvar produto: " + err.message);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;

    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;

    if (receiptUrl) message += `\n\n🖼️ *Comprovante:* ${receiptUrl}`;

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-xs uppercase tracking-widest text-primary animate-pulse">Sincronizando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;
                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + 1} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: 1, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={storageReady}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ variants: updated.map(v => ({...v, is_active: v.isActive})) }).eq('id', pId);
                }
              }}
              onReorderProduct={async (id, dir) => {
                const idx = products.findIndex(p => p.id === id);
                const target = dir === 'up' ? idx - 1 : idx + 1;
                if (target < 0 || target >= products.length) return;
                const next = [...products];
                [next[idx], next[target]] = [next[target], next[idx]];
                setProducts(next);
                // Atualização silenciosa de order_index se a coluna existir, senão apenas local
                next.forEach(async (p, i) => {
                   try {
                     await supabase.from('products').update({ order_index: i }).eq('id', p.id);
                   } catch(e) {}
                });
              }}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Deseja realmente excluir este produto?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={storageReady}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      window.scrollTo({ top: document.getElementById('checkout-form')?.offsetTop || 0, behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Gerando Comprovante...');

    try {
      let receiptUrl = undefined;

      if (receiptRef.current) {
        // Delay para garantir que o DOM está pronto e fontes carregadas
        await new Promise(r => setTimeout(r, 400));

        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          allowTaint: true,
          backgroundColor: '#ffffff',
          logging: false,
          width: receiptRef.current.scrollWidth,
          height: receiptRef.current.scrollHeight
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          setProcessingStatus('Finalizando Pedido...');
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          const { error: uploadError } = await supabase.storage
            .from('product-images')
            .upload(fileName, file);

          if (!uploadError) {
            const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
            receiptUrl = data.publicUrl;
          }
        }
      }
      onSendWhatsApp(paymentMethod, receiptUrl);
    } catch (err) {
      console.error("Erro no processamento:", err);
      onSendWhatsApp(paymentMethod); 
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  return (
    <div className="flex-1 w-full max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-md flex flex-col items-center justify-center text-white text-center p-6 animate-in fade-in">
