  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName})`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;

    if (receiptUrl) {
      message += `\n\n🖼️ *Comprovante:* ${receiptUrl}`;
    } else if (storageReady === 'error') {
      message += `\n\n⚠️ _Comprovante visual não gerado (Storage não configurado)_`;
    }

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark font-display">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-xs uppercase tracking-widest text-primary animate-pulse">Sincronizando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;
                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + 1} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: 1, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={storageReady}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ variants: updated.map(v => ({...v, is_active: v.isActive})) }).eq('id', pId);
                }
              }}
              onReorderProduct={async (id, dir) => {
                const idx = products.findIndex(p => p.id === id);
                const target = dir === 'up' ? idx - 1 : idx + 1;
                if (target < 0 || target >= products.length) return;
                const next = [...products];
                [next[idx], next[target]] = [next[target], next[idx]];
                setProducts(next);
              }}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Deseja realmente excluir este produto?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={storageReady}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      window.scrollTo({ top: document.getElementById('checkout-form')?.offsetTop || 0, behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Finalizando Pedido...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        await new Promise(r => setTimeout(r, 400));

        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          allowTaint: true,
          backgroundColor: '#ffffff',
          logging: false,
          width: receiptRef.current.scrollWidth,
          height: receiptRef.current.scrollHeight
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          const { error: uploadError } = await supabase.storage
            .from('product-images')
            .upload(fileName, file);

          if (!uploadError) {
            const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
            receiptUrl = data.publicUrl;
          }
        }
      }
    } catch (err) {
      console.warn("Erro ao gerar comprovante visual, prosseguindo apenas com texto:", err);
    } finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  return (
    <div className="flex-1 w-full max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-md flex flex-col items-center justify-center text-white text-center p-6 animate-in fade-in">
          <div className="w-14 h-14 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-lg uppercase tracking-widest animate-pulse">{processingStatus}</p>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 flex items-center justify-center rounded-2xl bg-primary text-black shadow-lg shadow-primary/20">
            <span className="material-symbols-outlined font-black">storefront</span>
          </div>
          <div>
            <h1 className="font-black text-sm uppercase tracking-tighter">Doce Mania</h1>
            <p className="text-[9px] font-bold text-primary uppercase italic leading-none">Qualidade & Sabor</p>
          </div>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4 mb-2">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-xs font-black uppercase tracking-wider transition-all shadow-sm ${selectedCategory === cat ? 'bg-primary text-black scale-105 shadow-primary/20' : 'bg-white dark:bg-white/5 border border-neutral-100 dark:border-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-6">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 p-4 rounded-3xl border border-neutral-100 dark:border-white/5 shadow-md hover:shadow-lg transition-shadow">
                <div className="aspect-[4/3] rounded-2xl overflow-hidden bg-neutral-50 dark:bg-black/20 mb-4 border border-neutral-100 dark:border-white/5 relative">
                  <img 
                    src={product.image} 
                    alt={product.name} 
                    className="w-full h-full object-cover transition-transform hover:scale-105 duration-500"
                    onError={(e) => { e.currentTarget.src = 'https://picsum.photos/400/300?text=Doce+Mania'; }}
                  />
                </div>
                <div className="mb-4 px-1">
                  <h3 className="font-black text-base text-text-main dark:text-white">{product.name}</h3>
                  {product.description && <p className="text-[11px] text-neutral-400 mt-1 line-clamp-2">{product.description}</p>}
                </div>
                <div className="space-y-2">
                  {activeVariants.map(v => {
                    const qty = getQuantity(product.id, v.id);
                    return (
                      <div key={v.id} className="flex items-center justify-between p-3 rounded-2xl bg-neutral-50 dark:bg-black/20 border border-transparent hover:border-primary/20 transition-all">
                        <div className="flex flex-col">
                          {activeVariants.length > 1 && <span className="text-[9px] font-black uppercase text-neutral-400 mb-0.5 tracking-widest">{v.name}</span>}
                          <span className="font-black text-primary-dark dark:text-primary text-sm">R$ {v.price.toFixed(2)}</span>
                        </div>
                        <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1 shadow-sm border border-neutral-100 dark:border-white/5">
                          {qty > 0 ? (
                            <>
                              <button onClick={() => removeFromCart(product.id, v.id)} className="w-8 h-8 flex items-center justify-center text-neutral-400 active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg">remove</span></button>
                              <span className="w-6 text-center text-xs font-black">{qty}</span>
                              <button onClick={() => addToCart(product, v.id)} className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-black">add</span></button>
                            </>
                          ) : (
                            <button onClick={() => addToCart(product, v.id)} className="px-5 py-2 text-[10px] font-black uppercase text-primary-dark dark:text-primary hover:bg-primary/5 rounded-lg transition-colors">Adicionar</button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-12 space-y-4">
            <div ref={receiptRef} className="p-6 bg-white text-black font-mono text-[11px] rounded shadow-2xl border-t-8 border-primary relative overflow-hidden">
              <div className="absolute top-0 right-0 w-20 h-20 bg-primary/5 -rotate-45 translate-x-10 -translate-y-10"></div>
              <h3 className="text-center font-black text-sm uppercase mb-1 tracking-tighter">DOCE MANIA</h3>
              <p className="text-center text-[9px] mb-4 opacity-60 italic">Sabor que transforma seu dia</p>
              <div className="border-b border-dashed border-neutral-300 pb-2 mb-4 flex justify-between opacity-60 text-[9px]">
                <span>{new Date().toLocaleDateString('pt-BR')}</span>
                <span>{new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <p className="mb-1 font-bold">CLIENTE: {clientName.toUpperCase() || '---'}</p>
              <p className="mb-4 font-bold">PAGAMENTO: {paymentMethod.toUpperCase()}</p>
              <div className="space-y-1.5 mb-4 border-b border-dashed border-neutral-300 pb-4">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between items-start">
                    <span className="flex-1 pr-2 uppercase">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="shrink-0">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-base pt-1">
                <span>TOTAL</span>
                <span className="text-primary-dark">R$ {total.toFixed(2)}</span>
              </div>
              <div className="mt-6 text-center opacity-40 italic text-[8px]">Obrigado pela preferência!</div>
            </div>

            <div className="bg-white dark:bg-white/5 p-6 rounded-3xl border border-neutral-100 dark:border-white/5 space-y-4 shadow-sm">
              <h2 className="text-xs font-black uppercase tracking-widest text-primary flex items-center gap-2">
                <span className="material-symbols-outlined text-sm">shopping_cart_checkout</span> Finalizar Pedido
              </h2>
              <div className="space-y-2">
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); if(e.target.value.trim().length >= 3) setShowNameError(false); }} 
                  placeholder="Seu nome completo..." 
                  className={`w-full p-4 rounded-2xl border bg-neutral-50 dark:bg-black/20 text-sm font-bold outline-none transition-all ${showNameError ? 'border-red-500 ring-2 ring-red-500/10' : 'border-neutral-100 dark:border-white/5 focus:ring-2 focus:ring-primary/20'}`}
                />
                {showNameError && <p className="text-[10px] text-red-500 font-black uppercase tracking-widest px-1">⚠️ Nome é obrigatório (mín. 3 letras)</p>}
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setPaymentMethod('Pix')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Pix' ? 'bg-primary/20 border-primary text-primary-dark' : 'bg-white dark:bg-white/5 border-neutral-100 dark:border-white/5 opacity-40'}`}>Pix</button>
                <button onClick={() => setPaymentMethod('Dinheiro')} className={`p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Dinheiro' ? 'bg-primary/20 border-primary text-primary-dark' : 'bg-white dark:bg-white/5 border-neutral-100 dark:border-white/5 opacity-40'}`}>Dinheiro</button>
              </div>
            </div>
          </div>
        )}
      </main>

      <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-background-light dark:from-background-dark via-background-light/95 dark:via-background-dark/95 to-transparent z-40">
        <button 
          onClick={handleConfirmOrder} 
          disabled={cart.length === 0 || isProcessing}
          className={`w-full py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${cart.length === 0 || isProcessing ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed' : 'bg-primary text-black shadow-primary/30'}`}
        >
          {isProcessing ? 'Enviando Pedido...' : 'Enviar pelo WhatsApp'}
        </button>
      </div>
    </div>
  );
};

