            <button onClick={onOpenCategories} className="flex-1 p-3 bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all active:scale-95">
              <span className="material-symbols-outlined text-sm">category</span> Marcas
            </button>
            <button onClick={onOpenVariations} className="flex-1 p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all active:scale-95">
              <span className="material-symbols-outlined text-sm">list_alt</span> Presets
            </button>
          </div>

          {isEditingPhone ? (
            <div className="flex gap-2 animate-in fade-in slide-in-from-top-1">
              <input 
