                onChange={(e) => setTempPhone(e.target.value)}
                className="flex-1 px-4 py-2 rounded-xl border dark:bg-black/20 text-sm focus:ring-2 focus:ring-primary outline-none"
                placeholder="DDD + Número"
              />
              <button onClick={handleSavePhone} className="px-4 py-2 bg-primary text-black font-bold rounded-xl text-xs">Salvar</button>
