import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, storageReady, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [imgStatus, setImgStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      if (productToEdit.image) setImgStatus('success');
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    // Extração inteligente de links de tags HTML ou códigos complexos
    if (raw.includes('<img') || raw.includes('<IMG')) {
      const match = raw.match(/src=["']([^"']+)["']/i);
      if (match && match[1]) raw = match[1];
    } else if (raw.includes('href=')) {
      const match = raw.match(/href=["']([^"']+)["']/i);
      if (match && match[1]) raw = match[1];
    }
    setImage(raw);
    setImgStatus(raw ? 'loading' : 'idle');
  };

  const uploadFile = async (file: File) => {
    // Permite tentativa de upload mesmo se o check falhou, para casos de erro temporário
    setIsUploading(true);
    setImgStatus('loading');
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
      setImgStatus('success');
    } catch (error: any) {
      console.error('Upload falhou:', error.message);
      // Se o erro for bucket não encontrado, avisamos amigavelmente
      if (error.message?.includes('not found')) {
        alert('ERRO DE CONFIGURAÇÃO:\nO bucket "product-images" não foi encontrado no seu Supabase. Por favor, crie-o no painel do Supabase ou use links diretos da internet.');
      } else {
        alert('Upload falhou: ' + error.message);
      }
      setImgStatus('error');
    } finally { setIsUploading(false); }
  };

  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Não foi possível acessar a câmera. Verifique as permissões.");
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);

        canvasRef.current.toBlob(async (blob) => {
          if (blob) {
            const file = new File([blob], `photo-${Date.now()}.jpg`, { type: 'image/jpeg' });
            await uploadFile(file);
          }
          stopCamera();
        }, 'image/jpeg', 0.8);
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9),
      isActive: true
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleSubmit = async () => {
    if (!name.trim()) return alert('Nome do produto é obrigatório!');
    if (!category) return alert('Selecione uma marca!');

    setIsSaving(true);
    try {
      const productData: Product = {
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Item+Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.map(v => ({ ...v, name: v.name || 'Padrão' }))
      };
      await onSave(productData);
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32 font-display">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 transition-colors"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-black uppercase tracking-tight">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center animate-in fade-in">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="absolute bottom-10 flex gap-6">
            <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/20 text-white flex items-center justify-center border-2 border-white shadow-2xl">
              <span className="material-symbols-outlined">close</span>
            </button>
            <button onClick={capturePhoto} className="w-20 h-20 rounded-full bg-primary text-black flex items-center justify-center shadow-2xl scale-110 active:scale-95 transition-transform">
              <span className="material-symbols-outlined text-4xl font-black">photo_camera</span>
            </button>
          </div>
        </div>
      )}

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Aviso amigável no topo do form */}
        {storageReady === 'error' && (
          <div className="p-4 bg-blue-50 border border-blue-100 rounded-3xl text-[10px] text-blue-700 font-bold leading-relaxed flex gap-2">
             <span className="material-symbols-outlined text-sm">tips_and_updates</span>
             <p>DICA: Você pode colar um link direto de qualquer foto da internet (Google, Pinterest, etc) ou até mesmo um código de imagem HTML no campo abaixo.</p>
          </div>
        )}

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary-dark mb-1.5 tracking-widest italic px-1">Nome do Item</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-2xl border bg-neutral-50 dark:bg-black/20 p-4 text-sm font-bold outline-none border-neutral-100 dark:border-white/5 focus:ring-2 focus:ring-primary/20 transition-all" placeholder="Ex: Batata Ruffles 140g" />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary-dark mb-1.5 tracking-widest italic px-1">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full rounded-2xl border bg-neutral-50 dark:bg-black/20 p-4 text-sm font-bold outline-none border-neutral-100 dark:border-white/5 focus:ring-2 focus:ring-primary/20">
              <option value="">Selecione a Marca...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary-dark mb-1.5 tracking-widest italic px-1">Descrição Curta</label>
            <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} className="w-full rounded-2xl border bg-neutral-50 dark:bg-black/20 p-4 text-sm outline-none border-neutral-100 dark:border-white/5 focus:ring-2 focus:ring-primary/20" placeholder="Ex: Sabor churrasco, crocante e fresquinha..." />
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase tracking-widest text-primary-dark flex items-center gap-2 px-1"><span className="material-symbols-outlined text-sm">image</span> Imagem do Produto</h2>

          <div className="space-y-3">
            <div className="flex gap-2">
              <input 
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
