                placeholder="Cole o link da foto ou código HTML..." 
              />
              {image && (
                <button 
                  onClick={() => { setImage(''); setImgStatus('idle'); }} 
                  className="w-14 h-14 flex items-center justify-center bg-red-50 dark:bg-red-900/10 text-red-500 rounded-2xl border border-red-100"
                >
                  <span className="material-symbols-outlined">delete</span>
                </button>
              )}
            </div>

            <div className="relative rounded-[2rem] border-2 border-dashed border-neutral-100 dark:border-white/10 aspect-video bg-neutral-50 dark:bg-black/40 flex flex-col items-center justify-center overflow-hidden transition-all group">
              {imgStatus === 'loading' && (
                <div className="absolute inset-0 bg-white/80 dark:bg-black/80 backdrop-blur-sm z-10 flex items-center justify-center">
                  <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                </div>
              )}

              {image ? (
                <img 
                  src={image} 
                  className="w-full h-full object-contain p-2" 
                  alt="Preview" 
                  onLoad={() => setImgStatus('success')}
                  onError={() => setImgStatus('error')} 
                />
              ) : (
                <div className="text-center opacity-30">
                  <span className="material-symbols-outlined text-5xl mb-1">image_search</span>
                  <p className="text-[10px] font-black uppercase tracking-widest">Aguardando Imagem</p>
