            {variants.map(v => (
              <div key={v.id} className="p-4 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5 flex flex-col gap-2">
                <div className="flex gap-2 items-center">
                  <input value={v.name} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? { ...x, name: e.target.value } : x))} className="flex-1 bg-transparent border-none p-0 text-sm font-black uppercase outline-none" placeholder="Ex: Unitário ou 140g" />
                  <button type="button" onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="w-8 h-8 flex items-center justify-center text-red-400 hover:bg-red-50 rounded-lg transition-colors"><span className="material-symbols-outlined text-lg">close</span></button>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-4 py-3 rounded-xl border border-neutral-100 dark:border-white/5 shadow-inner">
                  <span className="text-neutral-400">R$</span>
                  <input type="number" step="0.01" value={v.price} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? { ...x, price: parseFloat(e.target.value) || 0 } : x))} className="w-full bg-transparent border-none p-0 outline-none font-black text-primary-dark" />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-4 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t flex gap-3 left-1/2 -translate-x-1/2 z-50">
        <button type="button" onClick={onCancel} className="flex-1 py-4 font-black uppercase tracking-widest text-[11px] rounded-2xl border border-neutral-200 active:scale-95 transition-transform">Cancelar</button>
        <button type="button" onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-black uppercase tracking-widest text-[11px] rounded-2xl shadow-xl shadow-primary/30 active:scale-95 transition-all">
          {isSaving ? 'Gravando...' : 'Salvar Produto'}
        </button>
      </div>
    </div>
  );
};

