              <button type="button" onClick={() => setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }])} className="text-[9px] font-black uppercase text-primary-dark bg-primary/10 px-3 py-2 rounded-xl border">+ Add</button>
            </div>
          </div>
          {showPresets && (
            <div className="p-3 bg-blue-50 rounded-2xl flex flex-wrap gap-2 animate-in fade-in">
              {presets.map(p => <button type="button" key={p.id} onClick={() => handleApplyPreset(p)} className="px-3 py-2 bg-white border text-[10px] font-black uppercase rounded-lg shadow-sm">{p.name}</button>)}
            </div>
          )}
          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="p-4 bg-neutral-50 dark:bg-black/20 rounded-2xl border flex flex-col gap-2">
                <div className="flex gap-2 items-center">
