                  <button type="button" onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="text-red-400"><span className="material-symbols-outlined text-lg">close</span></button>
                </div>
                <div className="flex items-center gap-1 bg-white dark:bg-black/40 px-3 py-2 rounded-xl border">
                  <span className="text-neutral-400 text-xs font-bold">R$</span>
                  <input type="number" step="0.01" value={v.price} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? { ...x, price: parseFloat(e.target.value) || 0 } : x))} className="w-full bg-transparent p-0 outline-none font-black text-primary-dark" />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-4 bg-white/95 backdrop-blur-md border-t flex gap-3 left-1/2 -translate-x-1/2 z-50">
        <button type="button" onClick={onCancel} className="flex-1 py-4 font-black uppercase text-[10px] rounded-2xl border">Sair</button>
        <button type="button" onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-black uppercase text-[10px] rounded-2xl shadow-xl shadow-primary/30">
          {isSaving ? 'Salvando...' : 'Confirmar Cadastro'}
        </button>
      </div>
    </div>
  );
};

