                  <div className="absolute -bottom-1 -right-1 bg-white dark:bg-surface-dark rounded-full w-5 h-5 flex items-center justify-center border shadow-sm">
                    <span className="material-symbols-outlined text-[10px] text-neutral-400">{expandedId === product.id ? 'expand_less' : 'expand_more'}</span>
                  </div>
                </div>

                <div className="flex-1 min-w-0" onClick={() => toggleExpand(product.id)}>
                  <h3 className="font-bold text-sm truncate">{product.name}</h3>
                  <p className="text-[10px] text-neutral-400 uppercase font-bold tracking-widest">{product.category}</p>
                </div>

                <div className="flex items-center gap-1">
                  <button onClick={() => onEditProduct(product)} className="w-9 h-9 flex items-center justify-center text-blue-500 bg-blue-50 dark:bg-blue-900/20 rounded-xl hover:bg-blue-100"><span className="material-symbols-outlined text-xl">edit</span></button>
                  <button onClick={() => onToggleStatus(product.id)} className={`w-9 h-9 flex items-center justify-center rounded-xl ${product.isActive ? 'text-green-500 bg-green-50 dark:bg-green-900/20' : 'text-neutral-300 bg-neutral-100 dark:bg-white/5'}`}><span className="material-symbols-outlined text-xl">{product.isActive ? 'visibility' : 'visibility_off'}</span></button>
                  <button onClick={() => onDeleteProduct(product.id)} className="w-9 h-9 flex items-center justify-center text-red-400 bg-red-50 dark:bg-red-900/20 rounded-xl hover:bg-red-100"><span className="material-symbols-outlined text-xl">delete</span></button>
                </div>
              </div>

              {/* Seção Expandida para Variações Individuais */}
              {expandedId === product.id && (
                <div className="bg-neutral-50 dark:bg-black/20 p-4 border-t border-neutral-100 dark:border-white/5 space-y-3 animate-in slide-in-from-top-2">
                  <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-1"><span className="material-symbols-outlined text-[12px]">inventory_2</span> Controle de Estoque</p>
                  {product.variants.map(v => (
                    <div key={v.id} className="flex items-center justify-between bg-white dark:bg-white/5 p-3 rounded-xl border border-neutral-100 dark:border-white/10 shadow-sm">
                      <div className="flex flex-col">
                        <span className="text-xs font-bold uppercase">{v.name}</span>
                        <span className="text-xs font-black text-primary-dark">R$ {v.price.toFixed(2)}</span>
                      </div>
                      <button 
                        onClick={() => onToggleVariantStatus(product.id, v.id)}
                        className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${v.isActive ? 'bg-primary text-black shadow-md shadow-primary/20' : 'bg-neutral-200 dark:bg-white/10 text-neutral-500'}`}
                      >
                        {v.isActive ? 'Em Estoque' : 'Esgotado'}
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
          {products.length === 0 && (
            <div className="py-20 text-center opacity-20">
              <span className="material-symbols-outlined text-6xl">shopping_basket</span>
              <p className="font-bold text-xs uppercase mt-2">Nenhum produto cadastrado</p>
            </div>
          )}
        </div>
      </div>

      {/* Barra de Navegação Flutuante do Admin */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md p-3 rounded-full shadow-2xl border border-neutral-200 dark:border-white/10 z-50">
        <button onClick={onBack} className="w-12 h-12 flex items-center justify-center rounded-full text-neutral-400 hover:bg-black/5 transition-colors"><span className="material-symbols-outlined text-2xl">storefront</span></button>
        <button onClick={onAddProduct} className="w-16 h-16 bg-primary text-black rounded-full flex items-center justify-center shadow-lg shadow-primary/40 active:scale-95 transition-transform"><span className="material-symbols-outlined text-4xl font-black">add</span></button>
        <button onClick={onLogout} className="w-12 h-12 flex items-center justify-center rounded-full text-red-400 hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors"><span className="material-symbols-outlined text-2xl">logout</span></button>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, storageReady, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [imgStatus, setImgStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      if (productToEdit.image) setImgStatus('success');
    }
  }, [productToEdit]);

  // Função para limpar e extrair apenas a URL se for código HTML
  const handleImageInput = (val: string) => {
    let raw = val.trim();

    // Tenta extrair src de uma tag <img> se houver
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }

    setImage(raw);
    setImgStatus(raw ? 'loading' : 'idle');
  };

  const uploadFile = async (file: File) => {
    if (storageReady === 'error') {
      alert('Upload Bloqueado: O bucket "product-images" não existe no Supabase. Por favor, use links externos de imagens.');
      return;
    }

    setIsUploading(true);
    setImgStatus('loading');
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
      setImgStatus('success');
    } catch (error: any) {
      console.error('Falha de Storage:', error.message);
      alert('Erro no Storage: Bucket não encontrado ou privado. Enquanto não configura o bucket "product-images" como PÚBLICO no painel do Supabase, use links da internet.');
      setImgStatus('error');
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Nome e Marca são obrigatórios.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform"><span className="material-symbols-outlined">close</span></button>
        <h1 className="font-bold text-sm uppercase tracking-widest">{productToEdit ? 'Editar Item' : 'Novo Item'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        {/* Identificação */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-sm font-bold outline-none border border-transparent focus:border-primary transition-all" placeholder="Ex: Batata Ruffles 140g" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-sm font-bold outline-none border border-transparent focus:border-primary transition-all">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        {/* Imagem */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Foto do Item</label>
            {storageReady === 'error' && <span className="text-[9px] font-black text-amber-500 uppercase flex items-center gap-1"><span className="material-symbols-outlined text-[12px]">cloud_off</span> Use Links Externos</span>}
          </div>

          <div className="flex gap-2">
            <input 
              value={image} 
              onChange={(e) => handleImageInput(e.target.value)} 
              className="flex-1 bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-xs outline-none border border-transparent focus:border-primary transition-all" 
              placeholder="Cole o link ou código <img ...>" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={storageReady === 'error'}
              className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${storageReady === 'error' ? 'bg-neutral-200 text-neutral-400 opacity-50 cursor-not-allowed' : 'bg-primary text-black active:scale-95 shadow-lg shadow-primary/20'}`}
              title={storageReady === 'error' ? 'Storage desativado' : 'Upload local'}
            >
              <span className="material-symbols-outlined">{storageReady === 'error' ? 'cloud_off' : 'upload'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />

          <div className="aspect-video rounded-xl bg-neutral-100 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative">
            {image ? (
              <img src={image} className="w-full h-full object-contain" onLoad={() => setImgStatus('success')} onError={() => setImgStatus('error')} />
            ) : (
              <div className="text-center opacity-20">
                <span className="material-symbols-outlined text-4xl">add_photo_alternate</span>
                <p className="text-[10px] font-bold uppercase mt-1">Vazio</p>
              </div>
            )}
            {isUploading && (
              <div className="absolute inset-0 bg-white/60 dark:bg-black/60 flex items-center justify-center backdrop-blur-sm">
                <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
              </div>
            )}
          </div>
          <p className="text-[9px] text-neutral-400 italic text-center">Dica: Se colar o código da imagem do Google ou site, extraímos o link sozinho.</p>
        </div>

        {/* Variações */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Preços e Tamanhos</h2>
            <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-bold text-blue-500 uppercase hover:underline">Presets</button>
          </div>

          {showPresets && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-xl animate-in fade-in">
              {presets.map(p => <button key={p.id} onClick={() => handleApplyPreset(p)} className="px-3 py-1.5 bg-white dark:bg-white/10 rounded-lg text-[10px] font-bold shadow-sm border border-neutral-200">{p.name}</button>)}
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="flex gap-2 items-center bg-neutral-50 dark:bg-black/10 p-2 rounded-xl border border-neutral-100">
                <input value={v.name} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} className="flex-1 bg-transparent p-2 text-xs font-bold uppercase outline-none" placeholder="Ex: 140g, Pote, Un..." />
                <div className="w-24 bg-white dark:bg-white/5 p-2 rounded-lg flex items-center gap-1 border border-neutral-200">
                  <span className="text-[9px] opacity-40 font-bold">R$</span>
                  <input type="number" step="0.01" value={v.price} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} className="w-full bg-transparent outline-none text-xs font-bold" />
                </div>
                <button onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="w-8 h-8 flex items-center justify-center text-red-400 hover:bg-red-50 rounded-lg transition-colors"><span className="material-symbols-outlined text-sm">close</span></button>
              </div>
            ))}
            <button onClick={() => setVariants([...variants, {id: Date.now().toString(), name: '', price: 0, isActive: true}])} className="w-full p-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-xl text-[10px] font-bold uppercase text-neutral-400 hover:text-primary transition-all">+ Adicionar Opção</button>
          </div>
        </div>
      </div>

      {/* Footer Fixo */}
      <div className="fixed bottom-0 w-full max-w-lg p-4 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-t flex gap-3 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-4 font-bold text-[10px] uppercase tracking-widest border border-neutral-200 dark:border-white/10 rounded-2xl active:scale-95 transition-transform">Cancelar</button>
        <button onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-bold text-[10px] uppercase tracking-widest rounded-2xl shadow-xl shadow-primary/30 active:scale-95 transition-transform">
          {isSaving ? 'Salvando...' : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));

        const sorted = [...normalized].sort((a, b) => a.name.localeCompare(b.name));
        setProducts(sorted);
      } else {
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err: any) {
      console.warn("Usando dados locais:", err.message);
      setProducts(INITIAL_PRODUCTS);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    try {
      const payload = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map((v: any) => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive
        })),
        is_active: product.isActive
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + err.message);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName})`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    if (receiptUrl) message += `\n\n🖼️ *Recibo:* ${receiptUrl}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark font-display">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-xs uppercase tracking-widest text-primary animate-pulse">Carregando Catálogo...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;
                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + 1} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: 1, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={true}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ variants: updated.map(v => ({...v, is_active: v.isActive})) }).eq('id', pId);
                }
              }}
              onReorderProduct={() => {}}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Excluir produto?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={true}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

