import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);
    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      console.error('Falha de Storage:', error.message);
      alert('Erro ao subir imagem. Tente usar um link direto da internet em vez de fazer upload.');
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Nome e Marca são obrigatórios.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform"><span className="material-symbols-outlined">close</span></button>
        <h1 className="font-bold text-sm uppercase tracking-widest">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Nome do Item</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-sm font-bold outline-none border border-transparent focus:border-primary transition-all" placeholder="Ex: Batata Ruffles 140g" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-sm font-bold outline-none border border-transparent focus:border-primary transition-all">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <label className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Foto (Link Direto ou Upload)</label>
          <div className="flex gap-2">
            <input value={image} onChange={(e) => handleImageInput(e.target.value)} className="flex-1 bg-neutral-100 dark:bg-black/20 p-4 rounded-xl text-xs outline-none border border-transparent focus:border-primary transition-all" placeholder="Cole o link da foto aqui..." />
            <button onClick={() => fileInputRef.current?.click()} className="w-12 h-12 rounded-xl flex items-center justify-center bg-primary text-black active:scale-95 shadow-lg shadow-primary/20 transition-all">
              <span className="material-symbols-outlined">upload</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />

          <div className="aspect-video rounded-xl bg-neutral-100 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative">
            {image ? <img src={image} className="w-full h-full object-contain" onError={(e) => e.currentTarget.src='https://picsum.photos/400/300?text=Link+Invalido'} /> : <span className="material-symbols-outlined text-4xl opacity-10">add_photo_alternate</span>}
            {isUploading && <div className="absolute inset-0 bg-white/60 dark:bg-black/60 flex items-center justify-center"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>}
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-neutral-400 ml-1">Variações e Preços</h2>
            <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-bold text-blue-500 uppercase">Presets</button>
          </div>
          {showPresets && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-xl animate-in fade-in">
              {presets.map(p => <button key={p.id} onClick={() => handleApplyPreset(p)} className="px-3 py-1.5 bg-white dark:bg-white/10 rounded-lg text-[10px] font-bold border border-neutral-200">{p.name}</button>)}
            </div>
          )}
          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="flex gap-2 items-center bg-neutral-50 dark:bg-black/10 p-2 rounded-xl border border-neutral-100">
                <input value={v.name} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} className="flex-1 bg-transparent p-2 text-xs font-bold uppercase outline-none" placeholder="Ex: 140g, P, Unid..." />
                <div className="w-24 bg-white dark:bg-white/5 p-2 rounded-lg flex items-center gap-1 border border-neutral-200">
                  <span className="text-[9px] opacity-40 font-bold">R$</span>
                  <input type="number" step="0.01" value={v.price} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} className="w-full bg-transparent outline-none text-xs font-bold" />
                </div>
                <button onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="w-8 h-8 flex items-center justify-center text-red-400"><span className="material-symbols-outlined text-sm">close</span></button>
              </div>
            ))}
            <button onClick={() => setVariants([...variants, {id: Date.now().toString(), name: '', price: 0, isActive: true}])} className="w-full p-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-xl text-[10px] font-bold uppercase text-neutral-400 hover:text-primary transition-all">+ Novo Tamanho</button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-4 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-t flex gap-3 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-4 font-bold text-[10px] uppercase tracking-widest border border-neutral-200 rounded-2xl">Cancelar</button>
        <button onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-bold text-[10px] uppercase tracking-widest rounded-2xl shadow-xl shadow-primary/30 active:scale-95 transition-transform">
          {isSaving ? 'Salvando...' : 'Confirmar'}
        </button>
      </div>
    </div>
  );
};

