                          className={`relative w-11 h-6 rounded-full transition-colors duration-200 outline-none ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                        >
                          <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform duration-200 shadow-md ${v.isActive ? 'translate-x-5' : 'translate-x-0'}`} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
          {products.length === 0 && <p className="text-center py-10 opacity-30 text-xs font-bold uppercase">Nenhum produto</p>}
        </div>
      </div>

      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md p-3 rounded-full shadow-2xl border border-neutral-200 dark:border-white/10 z-50">
        <button onClick={onBack} className="w-12 h-12 flex items-center justify-center rounded-full text-neutral-400 hover:bg-black/5 transition-colors"><span className="material-symbols-outlined text-2xl">storefront</span></button>
        <button onClick={onAddProduct} className="w-16 h-16 bg-primary text-black rounded-full flex items-center justify-center shadow-lg shadow-primary/40 active:scale-95 transition-transform"><span className="material-symbols-outlined text-4xl font-black">add</span></button>
        <button onClick={onLogout} className="w-12 h-12 flex items-center justify-center rounded-full text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"><span className="material-symbols-outlined text-2xl">logout</span></button>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);
    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(`products/${fileName}`, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Dica: Use um link direto da imagem se o upload falhar.');
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Preencha o Nome e a Marca.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-xs uppercase tracking-widest">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all" 
              placeholder="Ex: Coca-Cola 2L" 
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all appearance-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Link ou HTML da Foto</label>
          <div className="flex gap-2">
            <input 
              value={image} 
              onChange={(e) => handleImageInput(e.target.value)} 
              className="flex-1 bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-xs font-bold outline-none border-2 border-transparent focus:border-primary transition-all" 
              placeholder="Cole link aqui..." 
            />
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="w-14 h-14 rounded-2xl flex items-center justify-center bg-primary text-black active:scale-95 shadow-lg shadow-primary/20 transition-all"
            >
              <span className="material-symbols-outlined">upload</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />

          <div className="aspect-square rounded-2xl bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative p-4">
            {image ? (
              <img src={image} className="w-full h-full object-contain rounded-xl" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
            ) : (
              <div className="text-center opacity-10">
                <span className="material-symbols-outlined text-5xl">image</span>
                <p className="text-[10px] font-black uppercase mt-2">Sem Imagem</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Preços e Estoque</h2>
            <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Presets</button>
          </div>

          {showPresets && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-2xl animate-in fade-in slide-in-from-top-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="px-4 py-2 bg-white dark:bg-white/10 rounded-xl text-[10px] font-black border border-neutral-200 shadow-sm active:scale-95 transition-transform uppercase tracking-tighter">
                  {p.name}
                </button>
              ))}
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className={`flex gap-3 items-center p-3 rounded-2xl border transition-all ${v.isActive ? 'bg-neutral-50 dark:bg-black/10 border-neutral-100 dark:border-white/5 shadow-sm' : 'bg-neutral-100/50 opacity-60 border-dashed border-red-100 grayscale'}`}>
                <div className="flex flex-col items-center gap-1">
                  <button 
                    onClick={() => toggleVariantStatus(v.id)}
                    className={`relative w-12 h-6 shrink-0 rounded-full transition-colors duration-200 outline-none ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                  >
                    <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform duration-200 shadow-sm ${v.isActive ? 'translate-x-6' : 'translate-x-0'}`} />
                  </button>
                  <span className={`text-[7px] font-black uppercase tracking-tighter transition-colors ${v.isActive ? 'text-green-600' : 'text-red-500'}`}>
                    {v.isActive ? 'ON' : 'OFF'}
                  </span>
                </div>

                <input 
                  value={v.name} 
                  onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} 
                  className={`flex-1 bg-transparent p-1 text-xs font-black uppercase outline-none ${!v.isActive && 'text-neutral-400 line-through'}`} 
                  placeholder="Ex: 2L" 
                />

                <div className="w-24 bg-white dark:bg-white/5 p-2 rounded-xl flex items-center gap-1 border border-neutral-200 dark:border-white/10 shadow-sm">
                  <span className="text-[9px] opacity-40 font-black">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    value={v.price} 
                    onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} 
                    className="w-full bg-transparent outline-none text-xs font-black" 
                  />
                </div>

                <button onClick={() => setVariants(prev => prev.filter(x => x.id !== v.id))} className="w-9 h-9 flex items-center justify-center text-red-400 hover:bg-red-50 rounded-xl transition-colors">
                  <span className="material-symbols-outlined text-base">close</span>
                </button>
              </div>
            ))}
            <button 
              onClick={() => setVariants([...variants, {id: Date.now().toString(), name: '', price: 0, isActive: true}])} 
              className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400 hover:text-primary hover:border-primary transition-all active:scale-95"
            >
              + NOVO TAMANHO/PREÇO
            </button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-6 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t flex gap-4 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-5 font-black text-[10px] uppercase tracking-widest border-2 border-neutral-100 dark:border-white/10 rounded-[2rem] active:scale-95 transition-all">
          Sair
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading} 
          className="flex-[2] py-5 bg-primary text-black font-black text-[10px] uppercase tracking-widest rounded-[2rem] shadow-2xl shadow-primary/40 active:scale-95 transition-all"
        >
          {isSaving ? 'SALVANDO...' : 'CONFIRMAR'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      window.scrollTo({ top: document.getElementById('checkout-form')?.offsetTop || 0, behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando Pedido...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-black font-black">DM</div>
          <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania</h1>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <h3 className="font-black text-lg mb-1 leading-tight">{product.name}</h3>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-4">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-3 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[9px] font-black text-neutral-400 uppercase tracking-widest">{v.name}</span>
                            <span className="font-black text-base text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                            {qty > 0 ? (
                              <>
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-lg flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </>
                            ) : (
                              <button onClick={() => addToCart(product, v.id)} className="px-6 py-2 text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-transform">Adicionar</button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - PEDIDO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-6 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2">
                <span>TOTAL</span>
                <span className="text-primary-dark">R$ {total.toFixed(2)}</span>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-6 rounded-3xl border border-neutral-100 dark:border-white/5 space-y-4 shadow-sm">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400 ml-1">Quem está pedindo?</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); if(e.target.value.trim().length >= 3) setShowNameError(false); }} 
                  placeholder="Digite seu nome completo..." 
                  className={`w-full p-4 rounded-2xl border bg-neutral-50 dark:bg-black/20 text-sm font-bold outline-none transition-all ${showNameError ? 'border-red-500 ring-4 ring-red-500/10' : 'border-transparent focus:border-primary'}`}
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setPaymentMethod('Pix')} className={`p-4 rounded-2xl border-2 font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Pix' ? 'bg-primary/5 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Pix</button>
                <button onClick={() => setPaymentMethod('Dinheiro')} className={`p-4 rounded-2xl border-2 font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Dinheiro' ? 'bg-primary/5 border-primary text-primary-dark' : 'border-neutral-100 dark:border-white/5 opacity-40'}`}>Dinheiro</button>
              </div>
            </div>
          </div>
        )}
      </main>

      <div className="fixed bottom-0 left-0 w-full p-6 bg-gradient-to-t from-background-light dark:from-background-dark via-background-light/95 dark:via-background-dark/95 to-transparent z-40">
        <button 
          onClick={handleConfirmOrder} 
          disabled={cart.length === 0 || isProcessing}
          className={`w-full py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.3em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all ${cart.length === 0 || isProcessing ? 'bg-neutral-200 text-neutral-400' : 'bg-primary text-black'}`}
        >
          {isProcessing ? 'PROCESSANDO...' : 'FECHAR PEDIDO NO WHATSAPP'}
          <span className="material-symbols-outlined text-base">send</span>
        </button>
      </div>
    </div>
  );
};

export default CatalogView;

import React, { useState } from 'react';
import { Product } from '../types';

interface AdminViewProps {
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  storageReady: boolean | 'error';
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
