};

export default AddProductForm;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    // Extração inteligente de src de tags <img> ou links diretos
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false); // Esconde o campo de link após upload bem sucedido
    } catch (error: any) {
      console.error("Erro no Storage:", error);
      alert(`Erro ao subir imagem: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Preencha Nome e Marca.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[10px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Item' : 'Novo Cadastro'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        {/* FOTO EM DESTAQUE */}
        <div className="bg-white dark:bg-white/5 p-4 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="aspect-square rounded-[2rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative group">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[10px] font-black uppercase mt-4 text-primary tracking-widest">Enviando...</p>
              </div>
            ) : image ? (
              <img src={image} className="w-full h-full object-contain p-4" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
            ) : (
              <div className="text-center opacity-20">
                <span className="material-symbols-outlined text-6xl">add_a_photo</span>
                <p className="text-[10px] font-black uppercase mt-2">Nenhuma Imagem</p>
              </div>
            )}

            {/* Overlay de Ações Rápidas */}
            {!isUploading && (
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 backdrop-blur-[2px]">
                <button onClick={() => fileInputRef.current?.click()} className="w-12 h-12 bg-white rounded-full flex items-center justify-center text-black shadow-xl active:scale-90 transition-transform">
                  <span className="material-symbols-outlined">upload_file</span>
                </button>
                <button onClick={() => setShowLinkInput(!showLinkInput)} className="w-12 h-12 bg-primary rounded-full flex items-center justify-center text-black shadow-xl active:scale-90 transition-transform">
                  <span className="material-symbols-outlined">link</span>
                </button>
              </div>
            )}
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="flex-1 py-4 bg-neutral-100 dark:bg-white/10 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined text-lg">image</span>
              {image ? 'Trocar Foto' : 'Subir Foto'}
            </button>
            <button 
              onClick={() => setShowLinkInput(!showLinkInput)}
              className={`flex-1 py-4 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all ${showLinkInput ? 'bg-primary text-black' : 'bg-neutral-100 dark:bg-white/10'}`}
            >
              <span className="material-symbols-outlined text-lg">link</span>
              Editar Link
            </button>
          </div>

          {showLinkInput && (
            <div className="animate-in slide-in-from-top-2 duration-300">
              <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-2 mb-1 block">Link Direto ou Tag HTML</label>
              <input 
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-xs font-bold outline-none border-2 border-primary/30 focus:border-primary transition-all" 
                placeholder="https://... ou <img src='...'>" 
              />
            </div>
          )}

          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />
        </div>

        {/* INFO BÁSICA */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all" 
              placeholder="Ex: Doritos 140g" 
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all appearance-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
