  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      setShowLinkInput(!productToEdit.image);
    } else {
      setShowLinkInput(true);
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false);
    } catch (error: any) {
      alert(`Erro no upload: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (confirm("Deseja realmente excluir esta variação?")) {
      setVariants(prev => prev.filter(x => x.id !== id));
    }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Por favor, preencha o Nome e a Marca.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[10px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Produto' : 'Cadastrar Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        {/* ÁREA DA IMAGEM */}
        <div className="bg-white dark:bg-white/5 p-4 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="aspect-square rounded-[2rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative group">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[10px] font-black uppercase mt-4 text-primary tracking-widest">Enviando Arquivo...</p>
              </div>
            ) : image ? (
              <img src={image} className="w-full h-full object-contain p-4" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
            ) : (
              <div className="text-center opacity-20">
                <span className="material-symbols-outlined text-6xl">image_search</span>
                <p className="text-[10px] font-black uppercase mt-2">Aguardando Imagem</p>
              </div>
            )}

            {image && !isUploading && (
              <button onClick={() => { if(confirm("Deseja remover a foto atual?")) { setImage(''); setShowLinkInput(true); } }} className="absolute top-4 right-4 w-10 h-10 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-transform">
                <span className="material-symbols-outlined text-xl">delete_forever</span>
              </button>
            )}
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="flex-1 py-4 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined text-lg">upload</span>
              {image ? 'Trocar Arquivo' : 'Escolher do PC'}
            </button>
            <button 
              onClick={() => setShowLinkInput(!showLinkInput)}
              className={`flex-1 py-4 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all ${showLinkInput ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10'}`}
            >
              <span className="material-symbols-outlined text-lg">edit_note</span>
              Editar Link
            </button>
          </div>

          {showLinkInput && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300 bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl border border-neutral-100 dark:border-white/5">
              <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 mb-2 block">Link da Imagem ou Código HTML</label>
              <textarea 
                rows={2}
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                className="w-full bg-white dark:bg-black/40 p-3 rounded-xl text-xs font-bold outline-none border-2 border-transparent focus:border-primary transition-all resize-none" 
                placeholder="Ex: https://... ou <img src='...'>" 
              />
            </div>
          )}

          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />
        </div>

        {/* DADOS DO PRODUTO */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all" 
              placeholder="Ex: Oreo 90g" 
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all appearance-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        {/* PREÇOS */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Variações e Preços</h2>
            <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Presets</button>
          </div>

          {showPresets && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-2xl animate-in fade-in slide-in-from-top-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="px-4 py-2 bg-white dark:bg-white/10 rounded-xl text-[10px] font-black border border-neutral-200 shadow-sm active:scale-95 transition-transform uppercase tracking-tighter">
                  {p.name}
                </button>
              ))}
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className={`flex gap-3 items-center p-3 rounded-2xl border transition-all ${v.isActive ? 'bg-neutral-50 dark:bg-black/10 border-neutral-100 dark:border-white/5 shadow-sm' : 'bg-red-50/5 opacity-60 border-dashed border-red-100 grayscale'}`}>
                <div className="flex flex-col items-center gap-1 shrink-0">
                  <button 
                    onClick={() => toggleVariantStatus(v.id)}
                    className={`relative w-11 h-6 rounded-full transition-all duration-300 outline-none ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                  >
                    <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${v.isActive ? 'translate-x-5' : 'translate-x-0'}`} />
                  </button>
                  <span className={`text-[7px] font-black uppercase tracking-tighter ${v.isActive ? 'text-green-600' : 'text-red-500'}`}>
                    {v.isActive ? 'ATIVO' : 'OFF'}
                  </span>
                </div>

                <input 
                  value={v.name} 
                  onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} 
                  className={`w-12 bg-transparent p-1 text-[10px] font-black uppercase outline-none transition-all ${!v.isActive && 'text-neutral-400 line-through'}`} 
                  placeholder="Tipo" 
                />

                <div className="flex-1 bg-white dark:bg-white/5 p-4 rounded-xl flex items-center gap-2 border border-neutral-200 dark:border-white/10 shadow-sm focus-within:border-primary transition-all">
                  <span className="text-[11px] opacity-40 font-black shrink-0">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    value={v.price} 
                    onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} 
                    className="w-full bg-transparent outline-none text-lg font-black" 
                  />
                </div>

                <button onClick={() => handleRemoveVariant(v.id)} className="w-10 h-10 flex items-center justify-center text-red-400 hover:bg-red-50 rounded-xl transition-colors shrink-0">
                  <span className="material-symbols-outlined text-base font-bold">close</span>
                </button>
              </div>
            ))}
            <button 
              onClick={() => setVariants([...variants, {id: Date.now().toString(), name: '', price: 0, isActive: true}])} 
              className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400 hover:text-primary hover:border-primary transition-all active:scale-95"
            >
              + NOVO TAMANHO/PREÇO
            </button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-6 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t flex gap-4 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-5 font-black text-[10px] uppercase tracking-widest border-2 border-neutral-100 dark:border-white/10 rounded-[2rem] active:scale-95 transition-all">
          Sair
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading} 
          className="flex-[2] py-5 bg-primary text-black font-black text-[10px] uppercase tracking-widest rounded-[2rem] shadow-2xl shadow-primary/40 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSaving ? 'SALVANDO...' : 'CONFIRMAR'}
        </button>
      </div>
    </div>
  );
};

