import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      const el = document.getElementById('checkout-form');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando Pedido...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  const isButtonDisabled = cart.length === 0 || isProcessing || !isNameValid;

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-2 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 flex items-center justify-center overflow-hidden">
             <img src="https://vvywceybsdfyyuwvsqnq.supabase.co/storage/v1/object/public/product-images/logo.png" alt="Doce Mania Logo" className="w-full h-full object-contain" />
          </div>
          <div className="flex flex-col -space-y-1">
            <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania</h1>
            <span className="text-[8px] font-bold text-neutral-400 uppercase tracking-widest">Atacadista</span>
          </div>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <h3 className="font-black text-lg mb-1 leading-tight">{product.name}</h3>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-4">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-3 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[9px] font-black text-neutral-400 uppercase tracking-widest">{v.name}</span>
                            <span className="font-black text-base text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                            {qty > 0 ? (
                              <>
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-lg flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </>
                            ) : (
                              <button onClick={() => addToCart(product, v.id)} className="px-6 py-2 text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-transform">Adicionar</button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - PEDIDO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-6 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Seu Nome * (Obrigatório)</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); setShowNameError(false); }} 
                  className={`w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 transition-all ${showNameError ? 'border-red-500' : 'border-transparent focus:border-primary'}`} 
                  placeholder="Como devemos te chamar?" 
                />
                {!isNameValid && clientName.length > 0 && <p className="text-[9px] font-bold text-neutral-400 ml-1 italic">Mínimo de 3 caracteres...</p>}
                {showNameError && <p className="text-[9px] font-bold text-red-500 ml-1">Por favor, informe seu nome para continuar.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Forma de Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['Pix', 'Dinheiro'] as const).map(method => (
                    <button 
                      key={method}
                      onClick={() => setPaymentMethod(method)}
                      className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${paymentMethod === method ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10 opacity-60'}`}
                    >
                      {method}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmOrder}
                  disabled={isButtonDisabled}
                  className={`w-full py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed shadow-none' : 'bg-primary text-black shadow-primary/40'}`}
                >
                  {isProcessing ? 'PROCESSANDO...' : 'FECHAR PEDIDO NO ZAP'}
                </button>
                {!isNameValid && (
                  <p className="text-center text-[9px] font-black text-neutral-400 uppercase tracking-widest animate-pulse-soft">Preencha seu nome para habilitar o envio</p>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CatalogView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      setShowLinkInput(!productToEdit.image);
    } else {
      setShowLinkInput(true);
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false);
    } catch (error: any) {
      alert(`Erro no upload: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (confirm("Deseja realmente excluir esta variação?")) {
      setVariants(prev => prev.filter(x => x.id !== id));
    }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) return alert('Por favor, preencha o Nome e a Marca.');
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name)
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full active:scale-95 transition-transform">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[10px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Produto' : 'Cadastrar Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        <div className="bg-white dark:bg-white/5 p-4 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="aspect-square rounded-[2rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative group">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[10px] font-black uppercase mt-4 text-primary tracking-widest">Enviando Arquivo...</p>
              </div>
            ) : image ? (
              <img src={image} className="w-full h-full object-contain p-4" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
            ) : (
              <div className="text-center opacity-20">
                <span className="material-symbols-outlined text-6xl">image_search</span>
                <p className="text-[10px] font-black uppercase mt-2">Aguardando Imagem</p>
              </div>
            )}

            {image && !isUploading && (
              <button onClick={() => { if(confirm("Deseja remover a foto atual?")) { setImage(''); setShowLinkInput(true); } }} className="absolute top-4 right-4 w-10 h-10 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-transform">
                <span className="material-symbols-outlined text-xl">delete_forever</span>
              </button>
            )}
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="flex-1 py-4 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined text-lg">upload</span>
              {image ? 'Trocar Arquivo' : 'Escolher do PC'}
            </button>
            <button 
              onClick={() => setShowLinkInput(!showLinkInput)}
              className={`flex-1 py-4 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all ${showLinkInput ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10'}`}
            >
              <span className="material-symbols-outlined text-lg">edit_note</span>
              Link Manual
            </button>
          </div>

          {showLinkInput && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300 bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl border border-neutral-100 dark:border-white/5">
              <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 mb-2 block">Link ou Código HTML da Imagem</label>
              <textarea 
                rows={2}
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                className="w-full bg-white dark:bg-black/40 p-3 rounded-xl text-xs font-bold outline-none border-2 border-transparent focus:border-primary transition-all resize-none" 
                placeholder="Ex: https://... ou <img src='...'>" 
              />
            </div>
          )}

          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} accept="image/*" />
        </div>

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all" 
              placeholder="Ex: Oreo 90g" 
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 border-transparent focus:border-primary transition-all appearance-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Variações e Preços</h2>
            <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Presets</button>
          </div>

          {showPresets && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 dark:bg-blue-900/10 rounded-2xl animate-in fade-in slide-in-from-top-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="px-4 py-2 bg-white dark:bg-white/10 rounded-xl text-[10px] font-black border border-neutral-200 shadow-sm active:scale-95 transition-transform uppercase tracking-tighter">
                  {p.name}
                </button>
              ))}
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className={`flex gap-3 items-center p-3 rounded-2xl border transition-all ${v.isActive ? 'bg-neutral-50 dark:bg-black/10 border-neutral-100 dark:border-white/5 shadow-sm' : 'bg-red-50/5 opacity-60 border-dashed border-red-100 grayscale'}`}>
                <div className="flex flex-col items-center gap-1 shrink-0">
                  <button 
                    onClick={() => toggleVariantStatus(v.id)}
                    className={`relative w-11 h-6 rounded-full transition-all duration-300 outline-none ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                  >
                    <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${v.isActive ? 'translate-x-5' : 'translate-x-0'}`} />
                  </button>
                  <span className={`text-[7px] font-black uppercase tracking-tighter ${v.isActive ? 'text-green-600' : 'text-red-500'}`}>
                    {v.isActive ? 'ATIVO' : 'OFF'}
                  </span>
                </div>

                <input 
                  value={v.name} 
                  onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} 
                  className={`w-12 bg-transparent p-1 text-[10px] font-black uppercase outline-none transition-all ${!v.isActive && 'text-neutral-400 line-through'}`} 
                  placeholder="Tipo" 
                />

                <div className="flex-1 bg-white dark:bg-white/5 p-4 rounded-xl flex items-center gap-2 border border-neutral-200 dark:border-white/10 shadow-sm focus-within:border-primary transition-all">
                  <span className="text-[11px] opacity-40 font-black shrink-0">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    value={v.price} 
                    onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} 
                    className="w-full bg-transparent outline-none text-xl font-black" 
                  />
                </div>

                <button onClick={() => handleRemoveVariant(v.id)} className="w-10 h-10 flex items-center justify-center text-red-400 hover:bg-red-50 rounded-xl transition-colors shrink-0">
                  <span className="material-symbols-outlined text-base font-bold">close</span>
                </button>
              </div>
            ))}
            <button 
              onClick={() => setVariants([...variants, {id: Date.now().toString(), name: '', price: 0, isActive: true}])} 
              className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400 hover:text-primary hover:border-primary transition-all active:scale-95"
            >
              + NOVO TAMANHO/PREÇO
            </button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full max-w-lg p-6 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t flex gap-4 left-1/2 -translate-x-1/2 z-50">
        <button onClick={onCancel} className="flex-1 py-5 font-black text-[10px] uppercase tracking-widest border-2 border-neutral-100 dark:border-white/10 rounded-[2rem] active:scale-95 transition-all">
          Sair
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading} 
          className="flex-[2] py-5 bg-primary text-black font-black text-[10px] uppercase tracking-widest rounded-[2rem] shadow-2xl shadow-primary/40 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSaving ? 'SALVANDO...' : 'CONFIRMAR'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [logoUrl, setLogoUrl] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));

        const sorted = [...normalized].sort((a, b) => a.name.localeCompare(b.name));
        setProducts(sorted);
      } else {
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        const logo = dbSettings.find(s => s.key === 'logo')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
        if (logo) setLogoUrl(logo);
      }
    } catch (err: any) {
      console.warn("Usando dados locais:", err.message);
      setProducts(INITIAL_PRODUCTS);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    try {
      const payload = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map((v: any) => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive
        })),
        is_active: product.isActive
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + err.message);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName})`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    if (receiptUrl) message += `\n\n🖼️ *Recibo:* ${receiptUrl}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark font-display">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-xs uppercase tracking-widest text-primary animate-pulse">Carregando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              logoUrl={logoUrl}
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;
                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + 1} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: 1, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              logoUrl={logoUrl}
              setLogoUrl={async (url) => {
                setLogoUrl(url);
                await supabase.from('settings').upsert({ key: 'logo', value: url }, { onConflict: 'key' });
              }}
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={true}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ 
                    variants: updated.map(v => ({
                      id: v.id,
                      name: v.name,
                      price: v.price,
                      is_active: v.isActive
                    })) 
                  }).eq('id', pId);
                }
              }}
              onReorderProduct={() => {}}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Excluir produto permanentemente?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={true}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  logoUrl?: string;
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  logoUrl, products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const [imgError, setImgError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isNameValid) {
      setShowNameError(true);
      const el = document.getElementById('checkout-form');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando Pedido...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/pedido-${Date.now()}.png`;
          const file = new File([blob], `pedido.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  const isButtonDisabled = cart.length === 0 || isProcessing || !isNameValid;

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-2 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-14 h-14 flex items-center justify-center">
             {logoUrl && !imgError ? (
               <img 
                 src={logoUrl} 
                 alt="Doce Mania" 
                 className="w-full h-full object-contain"
                 onError={() => setImgError(true)}
               />
             ) : (
               <div className="w-12 h-12 bg-primary rounded-xl flex items-center justify-center text-black font-black text-lg">DM</div>
             )}
          </div>
          <div className="flex flex-col -space-y-1">
            <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania</h1>
            <span className="text-[8px] font-bold text-neutral-400 uppercase tracking-widest">Atacadista</span>
          </div>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <h3 className="font-black text-lg mb-1 leading-tight">{product.name}</h3>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-4">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-3 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[9px] font-black text-neutral-400 uppercase tracking-widest">{v.name}</span>
                            <span className="font-black text-base text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-xl p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                            {qty > 0 ? (
                              <>
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-lg flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </>
                            ) : (
                              <button onClick={() => addToCart(product, v.id)} className="px-6 py-2 text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-transform">Adicionar</button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - PEDIDO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-6 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Seu Nome * (Obrigatório)</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); setShowNameError(false); }} 
                  className={`w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 transition-all ${showNameError ? 'border-red-500' : 'border-transparent focus:border-primary'}`} 
                  placeholder="Como devemos te chamar?" 
                />
                {!isNameValid && clientName.length > 0 && <p className="text-[9px] font-bold text-neutral-400 ml-1 italic">Mínimo de 3 caracteres...</p>}
                {showNameError && <p className="text-[9px] font-bold text-red-500 ml-1">Por favor, informe seu nome para continuar.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Forma de Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['Pix', 'Dinheiro'] as const).map(method => (
                    <button 
                      key={method}
                      onClick={() => setPaymentMethod(method)}
                      className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${paymentMethod === method ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10 opacity-60'}`}
                    >
                      {method}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmOrder}
                  disabled={isButtonDisabled}
                  className={`w-full py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed shadow-none' : 'bg-primary text-black shadow-primary/40'}`}
                >
                  {isProcessing ? 'PROCESSANDO...' : 'FECHAR PEDIDO NO ZAP'}
                </button>
                {!isNameValid && (
                  <p className="text-center text-[9px] font-black text-neutral-400 uppercase tracking-widest animate-pulse-soft">Preencha seu nome para habilitar o envio</p>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CatalogView;

import React, { useState, useRef } from 'react';
import { Product } from '../types';
import { supabase } from '../supabase';

interface AdminViewProps {
  logoUrl?: string;
  setLogoUrl: (url: string) => void;
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  storageReady: boolean | 'error';
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
  onReorderProduct: (id: string, direction: 'up' | 'down') => void;
  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  logoUrl,
  setLogoUrl,
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  onToggleStatus, 
  onToggleVariantStatus,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onBack, 
  onLogout 
}) => {
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [isUploadingLogo, setIsUploadingLogo] = useState(false);
  const [tempPhone, setTempPhone] = useState(whatsappNumber);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const handleSavePhone = () => {
    const cleaned = tempPhone.replace(/\D/g, '');
    if (cleaned.length < 10) return;
    setWhatsappNumber(cleaned);
    setIsEditingPhone(false);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploadingLogo(true);
    try {
      const fileName = `settings/logo-${Date.now()}.png`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
      setLogoUrl(data.publicUrl);
    } catch (err: any) {
      alert("Erro ao enviar logo: " + err.message);
    } finally {
      setIsUploadingLogo(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5">
            <span className="material-symbols-outlined">arrow_back</span>
          </button>
          <h1 className="font-bold text-base">Painel Admin</h1>
        </div>
        <button onClick={onLogout} className="text-red-500 font-bold text-xs uppercase tracking-widest px-4 py-2 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-xl">Sair</button>
      </div>

      <div className="p-4 space-y-6">
        {/* Gestão Rápida */}
        <div className="bg-white dark:bg-white/5 p-4 rounded-2xl border shadow-sm space-y-4">
          <div className="flex gap-2">
            <button onClick={onOpenCategories} className="flex-1 p-3 bg-neutral-100 dark:bg-white/10 rounded-xl flex items-center justify-center gap-2 text-[10px] font-bold uppercase active:scale-95 transition-all">
              <span className="material-symbols-outlined text-sm">category</span> Marcas
            </button>
            <button onClick={onOpenVariations} className="flex-1 p-3 bg-neutral-100 dark:bg-white/10 rounded-xl flex items-center justify-center gap-2 text-[10px] font-bold uppercase active:scale-95 transition-all">
              <span className="material-symbols-outlined text-sm">list_alt</span> Presets
            </button>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between px-3 py-3 bg-neutral-50 dark:bg-black/20 rounded-xl border border-neutral-100 dark:border-white/5">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white dark:bg-white/10 rounded-lg flex items-center justify-center overflow-hidden border">
                  {logoUrl ? (
                    <img src={logoUrl} className="w-full h-full object-contain" />
                  ) : (
                    <span className="material-symbols-outlined text-neutral-300">image</span>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Logotipo</span>
                  <span className="text-xs font-bold">{isUploadingLogo ? 'Enviando...' : (logoUrl ? 'Configurado' : 'Não definido')}</span>
                </div>
              </div>
              <button 
                onClick={() => logoInputRef.current?.click()}
                disabled={isUploadingLogo}
                className="text-[10px] font-bold text-primary uppercase hover:bg-primary/10 px-3 py-1.5 rounded-lg border border-primary/20"
              >
                Alterar Logo
              </button>
              <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
            </div>

            <div className="flex items-center justify-between px-3 py-3 bg-neutral-50 dark:bg-black/20 rounded-xl border border-neutral-100 dark:border-white/5">
              <div className="flex items-center gap-3">
                <span className="material-symbols-outlined text-green-500">whatsapp</span>
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">WhatsApp</span>
                  {isEditingPhone ? (
                    <input value={tempPhone} onChange={(e) => setTempPhone(e.target.value)} onBlur={handleSavePhone} autoFocus className="bg-transparent border-b border-primary outline-none font-bold text-sm w-32" />
                  ) : (
                    <span className="font-bold text-sm tracking-tight">{whatsappNumber}</span>
                  )}
                </div>
              </div>
              <button onClick={() => setIsEditingPhone(!isEditingPhone)} className="text-[10px] font-bold text-primary uppercase hover:bg-primary/10 px-3 py-1.5 rounded-lg border border-primary/20">
                {isEditingPhone ? 'Salvar' : 'Alterar Zap'}
              </button>
            </div>
          </div>
        </div>

        {/* Lista de Produtos */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-1">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Seus Produtos ({products.length})</h2>
          </div>
          {products.map((product) => (
            <div key={product.id} className={`bg-white dark:bg-white/5 rounded-2xl border transition-all ${!product.isActive ? 'opacity-50 grayscale' : 'shadow-sm border-neutral-200 dark:border-white/5'}`}>
              <div className="p-3 flex items-center gap-3">
                <div onClick={() => toggleExpand(product.id)} className="cursor-pointer shrink-0 relative">
                  <img src={product.image} className="w-14 h-14 rounded-xl object-cover bg-neutral-100 border dark:border-white/10" onError={(e) => e.currentTarget.src='https://picsum.photos/100/100?text=IMG'} />
