                    <span className="material-symbols-outlined text-[10px] text-neutral-400">{expandedId === product.id ? 'expand_less' : 'expand_more'}</span>
                  </div>
                </div>

                <div className="flex-1 min-w-0" onClick={() => toggleExpand(product.id)}>
                  <h3 className="font-bold text-sm truncate">{product.name}</h3>
                  <p className="text-[10px] text-neutral-400 uppercase font-bold tracking-widest">{product.category}</p>
                </div>

                <div className="flex items-center gap-1">
                  <button onClick={() => onEditProduct(product)} className="w-9 h-9 flex items-center justify-center text-blue-500 bg-blue-50 dark:bg-blue-900/20 rounded-xl hover:bg-blue-100 active:scale-90 transition-all"><span className="material-symbols-outlined text-xl">edit</span></button>
                  <button onClick={() => onToggleStatus(product.id)} className={`w-9 h-9 flex items-center justify-center rounded-xl active:scale-90 transition-all ${product.isActive ? 'text-green-500 bg-green-50 dark:bg-green-900/20' : 'text-neutral-300 bg-neutral-100 dark:bg-white/5'}`}><span className="material-symbols-outlined text-xl">{product.isActive ? 'visibility' : 'visibility_off'}</span></button>
                  <button onClick={() => onDeleteProduct(product.id)} className="w-9 h-9 flex items-center justify-center text-red-500 bg-red-50 dark:bg-red-900/20 rounded-xl hover:bg-red-100 active:scale-90 transition-all" title="Excluir Produto"><span className="material-symbols-outlined text-xl">delete</span></button>
                </div>
              </div>

              {expandedId === product.id && (
                <div className="bg-neutral-50 dark:bg-black/20 p-4 border-t border-neutral-100 dark:border-white/5 space-y-3 animate-in slide-in-from-top-2">
                  <div className="flex items-center justify-between px-1 mb-1">
                    <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-widest flex items-center gap-1">
                      <span className="material-symbols-outlined text-[12px]">inventory_2</span> Controle de Estoque
                    </p>
                  </div>
                  {product.variants.map(v => (
                    <div key={v.id} className={`flex items-center justify-between bg-white dark:bg-white/5 p-3 rounded-xl border transition-all ${v.isActive ? 'border-neutral-100 dark:border-white/10' : 'border-dashed border-red-200/50 bg-red-50/10 grayscale'}`}>
                      <div className="flex flex-col">
                        <span className={`text-xs font-bold uppercase transition-all ${!v.isActive ? 'text-neutral-400 line-through' : ''}`}>{v.name}</span>
                        <span className="text-xs font-black text-primary-dark">R$ {v.price.toFixed(2)}</span>
                      </div>

                      <div className="flex items-center gap-3">
                        <span className={`text-[8px] font-black uppercase tracking-tighter transition-colors ${v.isActive ? 'text-green-500' : 'text-red-500'}`}>
                          {v.isActive ? 'Disponível' : 'Esgotado'}
                        </span>
                        <button 
                          onClick={() => onToggleVariantStatus(product.id, v.id)}
                          className={`relative w-11 h-6 rounded-full transition-all duration-300 outline-none ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                        >
                          <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${v.isActive ? 'translate-x-5' : 'translate-x-0'}`} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
          {products.length === 0 && <p className="text-center py-10 opacity-30 text-xs font-bold uppercase">Nenhum produto cadastrado</p>}
        </div>
      </div>

      {/* Botão Flutuante Central */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md p-3 rounded-full shadow-2xl border border-neutral-200 dark:border-white/10 z-50">
        <button onClick={onBack} className="w-12 h-12 flex items-center justify-center rounded-full text-neutral-400 hover:bg-black/5 transition-colors"><span className="material-symbols-outlined text-2xl">storefront</span></button>
        <button onClick={onAddProduct} className="w-16 h-16 bg-primary text-black rounded-full flex items-center justify-center shadow-lg shadow-primary/40 active:scale-95 transition-transform"><span className="material-symbols-outlined text-4xl font-black">add</span></button>
        <button onClick={onLogout} className="w-12 h-12 flex items-center justify-center rounded-full text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"><span className="material-symbols-outlined text-2xl">logout</span></button>
      </div>
    </div>
  );
};

