  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  logoUrl,
  setLogoUrl,
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  onToggleStatus, 
  onToggleVariantStatus,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onBack, 
  onLogout 
