import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      setShowLinkInput(!productToEdit.image || !productToEdit.image.includes('supabase'));
    } else {
      setShowLinkInput(true);
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    // Regex robusto para extrair SRC de tags <img> ou capturar URLs puras
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false);
    } catch (error: any) {
      alert(`Erro no upload: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (confirm("Deseja realmente excluir esta variação?")) {
      setVariants(prev => prev.filter(x => x.id !== id));
    }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) {
      alert('Por favor, preencha o Nome do Produto e a Marca/Categoria.');
      return;
    }
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name),
        order_index: productToEdit?.order_index
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-40 text-neutral-900 dark:text-neutral-50">
      {/* Cabeçalho */}
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-4 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-neutral-100 dark:hover:bg-white/5 active:scale-95 transition-all">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[11px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Produto' : 'Cadastrar Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-6">
        {/* Card de Imagem conforme Screenshot */}
        <div className="bg-white dark:bg-white/5 p-4 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-5">
          <div className="aspect-square rounded-[2.5rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative group">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[9px] font-black uppercase mt-4 text-primary tracking-widest">Processando Imagem...</p>
              </div>
            ) : image ? (
              <>
                <img src={image} className="w-full h-full object-contain p-6" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Formato+Invalido'} />
                <button onClick={() => setImage('')} className="absolute top-4 right-4 w-10 h-10 bg-red-500 text-white rounded-full shadow-lg flex items-center justify-center active:scale-90 transition-all">
                  <span className="material-symbols-outlined">delete</span>
                </button>
              </>
            ) : (
              <div className="text-center opacity-30 flex flex-col items-center">
                <span className="material-symbols-outlined text-6xl mb-4">image</span>
                <p className="text-[10px] font-black uppercase tracking-widest">Nenhuma foto selecionada</p>
              </div>
            )}
          </div>

          <div className="flex gap-3">
            <button onClick={() => fileInputRef.current?.click()} className="flex-1 py-4 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-700 dark:text-emerald-400 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all">
              <span className="material-symbols-outlined text-xl">upload</span> 
              Trocar Arquivo
            </button>
            <button onClick={() => setShowLinkInput(!showLinkInput)} className="flex-1 py-4 bg-neutral-100 dark:bg-white/5 text-neutral-500 dark:text-neutral-400 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all">
              <span className="material-symbols-outlined text-xl">link</span> 
              Link Manual
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} />
          </div>

          {showLinkInput && (
            <div className="space-y-2 animate-in slide-in-from-top-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Colar link ou código HTML</label>
              <input 
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                placeholder="https://..." 
                className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-xs font-medium outline-none border border-neutral-200 dark:border-white/10"
              />
            </div>
          )}
        </div>

        {/* Informações Básicas */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary transition-all" placeholder="Ex: Doritos Nacho" />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary appearance-none transition-all">
              <option value="">Selecione...</option>
              {categories.filter(c => c !== 'Todas').map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        </div>

        {/* Variações e Preços */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
          <div className="flex items-center justify-between px-1">
             <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400">Variações e Preços</label>
             <button onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black uppercase tracking-widest text-primary flex items-center gap-1"><span className="material-symbols-outlined text-sm">auto_awesome</span> Presets</button>
          </div>

          {showPresets && (
            <div className="grid grid-cols-2 gap-2 p-2 bg-neutral-50 dark:bg-black/20 rounded-2xl animate-in fade-in zoom-in duration-200">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="p-3 text-[9px] font-black uppercase bg-white dark:bg-white/5 rounded-xl border border-neutral-100 dark:border-white/10 active:scale-95 transition-all">{p.name}</button>
              ))}
            </div>
          )}

          <div className="space-y-3">
            {variants.map((v, idx) => (
              <div key={v.id} className="flex items-center gap-2 animate-in slide-in-from-left duration-200" style={{ animationDelay: `${idx * 50}ms` }}>
                <input value={v.name} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} className="flex-1 bg-neutral-50 dark:bg-black/20 p-3 rounded-xl text-xs font-black outline-none" placeholder="Nome (Ex: 140g)" />
                <div className="relative w-28">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black opacity-30">R$</span>
                  <input type="number" value={v.price || ''} onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} className="w-full bg-neutral-50 dark:bg-black/20 p-3 pl-8 rounded-xl text-xs font-black outline-none" placeholder="0,00" />
                </div>
                <button onClick={() => handleRemoveVariant(v.id)} className="w-10 h-10 flex items-center justify-center text-red-500 bg-red-50 dark:bg-red-900/10 rounded-xl active:scale-90 transition-all"><span className="material-symbols-outlined text-sm">remove</span></button>
              </div>
            ))}
            <button onClick={() => setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }])} className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest opacity-50 hover:opacity-100 transition-all">+ Adicionar Variação</button>
          </div>
        </div>
      </div>

      {/* Botões de Ação do Rodapé Conforme Screenshot */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t border-neutral-100 dark:border-white/10 z-50 flex gap-4">
        <button onClick={onCancel} className="flex-1 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] bg-neutral-100 dark:bg-white/5 active:scale-95 transition-all">Sair</button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving}
          className="flex-[2] py-5 bg-primary text-black rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-primary/30 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSaving ? 'Salvando...' : 'Confirmar'}
        </button>
      </div>
    </div>
  );
};

