                  </p>
                </div>

                {!isNameValid && isMinOrderMet && (
                  <p className="text-center text-[9px] font-black text-neutral-400 uppercase tracking-widest animate-pulse-soft mt-2">Identifique-se para aproveitar estas ofertas</p>
