                  <div className="space-y-3.5">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-black/20 rounded-3xl border border-neutral-100 dark:border-white/5 transition-all hover:bg-neutral-100 dark:hover:bg-white/10">
                          <div className="flex flex-col">
                            <span className="text-[10px] font-black text-neutral-400 uppercase tracking-widest mb-1">{v.name}</span>
                            <div className="flex items-center gap-2">
                                <span className="font-black text-lg text-primary-dark">R$ {v.price.toFixed(2)}</span>
                                <span className="text-[7px] font-black uppercase text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded-md tracking-widest border border-emerald-500/20">OFERTA</span>
                            </div>
                          </div>
                          <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-2xl p-2 shadow-sm border border-neutral-100 dark:border-white/5">
                            {qty > 0 ? (
                              <>
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-10 h-10 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-xl">remove</span></button>
                                <span className="w-5 text-center text-base font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center text-black active:scale-90 transition-transform shadow-lg shadow-primary/20"><span className="material-symbols-outlined text-xl font-bold">add</span></button>
                              </>
                            ) : (
                              <button onClick={() => addToCart(product, v.id)} className="px-7 py-2.5 text-[11px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-transform flex items-center gap-2">
                                <span className="material-symbols-outlined text-sm">add_shopping_cart</span>
                                Adicionar
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-20 space-y-8 pb-10">
