              <h3 className="text-center font-black text-base uppercase mb-6 tracking-tight border-b-2 border-black pb-2">DOCE MANIA - ATACADO</h3>
              <div className="space-y-1.5 mb-6 border-b border-dashed border-neutral-400 pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
