                <p className="text-[9px] uppercase font-bold tracking-widest">Sujeito a conferência de estoque.</p>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[3rem] border border-neutral-100 dark:border-white/5 shadow-2xl space-y-8">
