        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {logoUrl && !imgError && (
            <div className="w-12 h-12 flex items-center justify-center">
               <img 
                 src={logoUrl} 
                 alt="Doce Mania" 
                 className="w-full h-full object-contain"
                 onError={() => setImgError(true)}
               />
            </div>
          )}
          <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania Atacado</h1>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        {/* Aviso de Preço Especial e Pedido Mínimo - Conforme Screenshot 1 */}
