import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  logoUrl?: string;
  canInstall?: boolean;
  onInstall?: () => void;
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  logoUrl, canInstall, onInstall, products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const [imgError, setImgError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const MIN_ORDER_VALUE = 200;
  const isMinOrderMet = total >= MIN_ORDER_VALUE;

  const isPepsicoProduct = (p: Product) => {
    const name = p.name.toLowerCase();
    const cat = p.category.toLowerCase();
    return cat === 'pepsico' || name.includes('toddynho') || name.includes('kero coco');
  };

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isMinOrderMet) return;
    if (!isNameValid) {
      setShowNameError(true);
      const el = document.getElementById('checkout-form');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/sugestao-${Date.now()}.png`;
          const file = new File([blob], `sugestao.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart?.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  const isButtonDisabled = cart.length === 0 || isProcessing || !isNameValid || !isMinOrderMet;

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      {/* Botão de Instalação PWA */}
      {canInstall && (
        <div className="bg-primary/10 border-b border-primary/20 px-4 py-2 flex items-center justify-between animate-in slide-in-from-top duration-500">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-primary-dark">install_mobile</span>
            <span className="text-[10px] font-black uppercase tracking-widest">Instale o App na tela inicial</span>
          </div>
          <button onClick={onInstall} className="bg-primary text-black px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest active:scale-95 transition-all shadow-sm">Instalar</button>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {logoUrl && !imgError && (
            <div className="w-12 h-12 flex items-center justify-center">
               <img 
                 src={logoUrl} 
                 alt="Doce Mania" 
                 className="w-full h-full object-contain"
                 onError={() => setImgError(true)}
               />
            </div>
          )}
          <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania Atacado</h1>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="mb-6 px-2 text-center">
          <p className="text-[10px] font-black uppercase tracking-widest text-primary-dark">
            🔥 PREÇOS EXCLUSIVOS DE ATACADO! 🔥
          </p>
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em] mt-1.5">
            PEDIDO MÍNIMO PARA ENTREGA: R$ 200,00
          </p>
        </div>

        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;
            const isPackItem = isPepsicoProduct(product);

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <div className="flex justify-between items-start mb-0.5">
                    <h3 className="font-black text-xl leading-tight">{product.name}</h3>
                    {isPackItem && (
                      <span className="bg-primary/20 text-primary-dark text-[8px] font-black px-2 py-1 rounded-md uppercase tracking-widest">Pack c/ 6</span>
                    )}
                  </div>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-6">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[10px] font-black text-neutral-400 uppercase tracking-widest">{v.name}</span>
                            <span className="font-black text-lg text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3">
                            {qty > 0 ? (
                              <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-full p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-full flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </div>
                            ) : (
                              <button 
                                onClick={() => addToCart(product, v.id)} 
                                className="bg-neutral-100 dark:bg-white/10 px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-all shadow-sm flex flex-col items-center"
                              >
                                <span>ADICIONAR</span>
                                {isPackItem && <span className="text-[7px] opacity-60 mt-0.5">(PACK 6UN)</span>}
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - ATACADO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-4 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2 mb-4">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
              <div className="text-center mt-6 pt-4 border-t border-dashed opacity-40">
                <p className="text-[8px] uppercase font-bold tracking-widest">Aviso: Preços especiais de atacado.</p>
                <p className="text-[8px] uppercase font-bold tracking-widest">Pedido sujeito a disponibilidade.</p>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Seu Nome * (Obrigatório)</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); setShowNameError(false); }} 
                  className={`w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 transition-all ${showNameError ? 'border-red-500' : 'border-transparent focus:border-primary'}`} 
                  placeholder="Como devemos te chamar?" 
                />
                {!isNameValid && clientName.length > 0 && <p className="text-[9px] font-bold text-neutral-400 ml-1 italic">Mínimo de 3 caracteres...</p>}
                {showNameError && <p className="text-[9px] font-bold text-red-500 ml-1">Por favor, informe seu nome para continuar.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Forma de Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['Pix', 'Dinheiro'] as const).map(method => (
                    <button 
                      key={method}
                      onClick={() => setPaymentMethod(method)}
                      className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${paymentMethod === method ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10 opacity-60'}`}
                    >
                      {method}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmOrder}
                  disabled={isButtonDisabled}
                  className={`w-full py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed shadow-none' : 'bg-primary text-black shadow-primary/40'}`}
                >
                  {isProcessing ? 'PROCESSANDO...' : !isMinOrderMet ? `FALTAM R$ ${(MIN_ORDER_VALUE - total).toFixed(2)} PARA O MÍNIMO` : 'ENVIAR PEDIDO DE ATACADO'}
                </button>

                <div className="text-center px-4 space-y-2">
                  {!isMinOrderMet && (
                    <p className="text-[9px] font-black text-red-500 uppercase tracking-widest animate-pulse">
                      Atingir R$ 200,00 libera os preços de atacado
                    </p>
                  )}
                  <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest leading-relaxed">
                    * Preços especiais de revenda válidos para<br/>pedidos acima de R$ 200,00.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CatalogView;

export interface ProductVariant {
  id: string;
  name: string;
  price: number;
  isActive: boolean;
}

export interface VariationPreset {
  id: string;
  name: string;
  variants: ProductVariant[];
}

export interface Product {
  id: string;
  name: string;
  description: string;
  image: string;
  category: string;
  isActive: boolean;
  variants: ProductVariant[];
  order_index?: number;
  units_per_box?: number; // Novo campo para múltiplos de venda
}

export interface CartItem {
  productId: string;
  variantId: string;
  quantity: number;
  productName: string;
  variantName: string;
  price: number;
}

export type AppView = 'catalog' | 'admin' | 'add-product' | 'edit-product' | 'login' | 'edit-categories' | 'edit-variations';

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5554991107242');
  const [logoUrl, setLogoUrl] = useState<string>('https://vvywceybsdfyyuwvsqnq.supabase.co/storage/v1/object/public/product-images/logo.png');

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('catalog_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    const handler = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  useEffect(() => {
    localStorage.setItem('catalog_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          units_per_box: p.units_per_box ?? 1,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));

        const sorted = [...normalized].sort((a, b) => (a.order_index ?? 9999) - (b.order_index ?? 9999));
        setProducts(sorted);
      } else {
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        const logo = dbSettings.find(s => s.key === 'logo')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
        if (logo) setLogoUrl(logo);
      }
    } catch (err: any) {
      console.warn("Usando dados locais:", err.message);
      setProducts(INITIAL_PRODUCTS);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const maxOrder = products.length > 0 ? Math.max(...products.map(p => p.order_index ?? 0)) : 0;

      const payload = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        units_per_box: product.units_per_box,
        variants: product.variants.map((v: any) => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive
        })),
        is_active: product.isActive,
        order_index: product.order_index ?? (maxOrder + 1)
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + err.message);
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const currentIndex = products.findIndex(p => p.id === id);
    if (currentIndex === -1) return;

    const targetIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = newProducts[currentIndex];
    const itemB = newProducts[targetIndex];

    const tempOrder = itemA.order_index ?? currentIndex;
    itemA.order_index = itemB.order_index ?? targetIndex;
    itemB.order_index = tempOrder;

    if (itemA.order_index === itemB.order_index) {
        if (direction === 'up') itemA.order_index--;
        else itemA.order_index++;
    }

    setProducts([...newProducts].sort((a, b) => (a.order_index ?? 9999) - (b.order_index ?? 9999)));

    try {
      await Promise.all([
        supabase.from('products').update({ order_index: itemA.order_index }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: itemB.order_index }).eq('id', itemB.id)
      ]);
    } catch (err) {
      console.error("Erro ao reordenar no banco:", err);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;

    const colDesc = 18;
    const colQty = 4;
    const colVal = 8;

    const header = "********************************\n" +
                   "*      CUPOM NÃO FISCAL        *\n" +
                   "********************************\n\n";

    const clientInfo = `👤 *Cliente:* ${clientName || 'Não identificado'}\n` +
                       `--------------------------------\n`;

    const tableHeader = "```" + 
                        "DESCRIÇÃO".padEnd(colDesc) + 
                        "QTD".padStart(colQty) + 
                        "VALOR".padStart(colVal) + "\n" +
                        "--------------------------------\n";

    const itemsText = cart.map(item => {
      const name = `${item.productName} (${item.variantName})`.substring(0, colDesc - 1).padEnd(colDesc);
      const qty = `${item.quantity}x`.padStart(colQty);
      const val = (item.price * item.quantity).toFixed(2).padStart(colVal);
      return `${name}${qty}${val}`;
    }).join('\n');

    const footerTable = "\n--------------------------------\n```";

    const totalValue = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const summary = `💰 *TOTAL:* R$ ${totalValue.toFixed(2)}\n` +
                    `💳 *PAGAMENTO:* ${paymentMethod}\n` +
                    `--------------------------------\n\n` +
                    `✅ *OBRIGADO PELA PREFERÊNCIA!*\n` +
                    `_Escaneie o QR Code e pague com PIX_`;

    let message = `${header}${clientInfo}${tableHeader}${itemsText}${footerTable}${summary}`;

    if (receiptUrl) {
      message += `\n\n🖼️ *VER RECIBO:* ${receiptUrl}`;
    }

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark font-display">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-xs uppercase tracking-widest text-primary animate-pulse">Iniciando App...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              logoUrl={logoUrl}
              canInstall={!!deferredPrompt}
              onInstall={handleInstall}
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;

                const step = p.units_per_box || 1;

                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + step} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: step, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                const product = products.find(p => p.id === pId);
                const step = product?.units_per_box || 1;

                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - step} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              logoUrl={logoUrl}
              setLogoUrl={async (url) => {
                setLogoUrl(url);
                await supabase.from('settings').upsert({ key: 'logo', value: url }, { onConflict: 'key' });
              }}
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={true}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ 
                    variants: updated.map(v => ({
                      id: v.id,
                      name: v.name,
                      price: v.price,
                      is_active: v.isActive
                    })) 
                  }).eq('id', pId);
                }
              }}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Excluir produto permanentemente?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={true}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [unitsPerBox, setUnitsPerBox] = useState<number>(1);
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setUnitsPerBox(productToEdit.units_per_box ?? 1);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ ...v, price: Number(v.price) })));
      setShowLinkInput(!productToEdit.image || !productToEdit.image.includes('supabase'));
    } else {
      setShowLinkInput(true);
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false);
    } catch (error: any) {
      alert(`Erro no upload: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ ...v, id: Math.random().toString(36).substr(2, 9), isActive: true })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert("O produto deve ter pelo menos uma variação.");
      return;
    }
    if (confirm("Deseja realmente excluir esta variação?")) {
      setVariants(prev => prev.filter(x => x.id !== id));
    }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) {
      alert('Por favor, preencha o Nome do Produto e a Marca/Categoria.');
      return;
    }
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        units_per_box: unitsPerBox,
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name),
        order_index: productToEdit?.order_index
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-44 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-neutral-100 dark:hover:bg-white/5 active:scale-95 transition-all">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[11px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Produto' : 'Cadastrar Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-4">
        <div className="bg-white dark:bg-white/5 p-3 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="aspect-square rounded-[1.5rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[8px] font-black uppercase mt-3 text-primary tracking-widest">Enviando...</p>
              </div>
            ) : image ? (
              <>
                <img src={image} className="w-full h-full object-contain p-2" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
                <button onClick={() => setImage('')} className="absolute top-3 right-3 w-8 h-8 bg-red-500 text-white rounded-full shadow-lg flex items-center justify-center active:scale-90 transition-all z-10">
                  <span className="material-symbols-outlined text-lg">delete</span>
                </button>
              </>
            ) : (
              <div className="text-center opacity-30 flex flex-col items-center">
                <span className="material-symbols-outlined text-5xl mb-2">image</span>
                <p className="text-[9px] font-black uppercase tracking-widest">Nenhuma foto</p>
              </div>
            )}
          </div>

          <div className="flex gap-2">
            <button onClick={() => fileInputRef.current?.click()} className="flex-1 py-3 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-700 dark:text-emerald-400 rounded-xl flex items-center justify-center gap-1.5 text-[8px] font-black uppercase tracking-widest active:scale-95 transition-all border border-emerald-100/50">
              <span className="material-symbols-outlined text-base">upload</span> 
              Trocar Arquivo
            </button>
            <button onClick={() => setShowLinkInput(!showLinkInput)} className="flex-1 py-3 bg-neutral-100 dark:bg-white/5 text-neutral-500 dark:text-neutral-400 rounded-xl flex items-center justify-center gap-1.5 text-[8px] font-black uppercase tracking-widest active:scale-95 transition-all border border-neutral-200/50">
              <span className="material-symbols-outlined text-base">link</span> 
              Link Manual
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} />
          </div>

          {showLinkInput && (
            <div className="animate-in slide-in-from-top-2 px-1">
              <input 
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                placeholder="Cole o link ou tag HTML aqui..." 
                className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-[11px] font-medium outline-none border border-neutral-200 dark:border-white/10 shadow-inner"
              />
            </div>
          )}
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary transition-all" placeholder="Ex: Cheetos Mix" />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
              <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary appearance-none transition-all">
                <option value="">Selecione...</option>
                {categories.filter(c => c !== 'Todas').map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-1">Unidades por Caixa</label>
              <input 
                type="number" 
                min="1" 
                value={unitsPerBox} 
                onChange={(e) => setUnitsPerBox(Math.max(1, parseInt(e.target.value) || 1))} 
                className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary transition-all text-center" 
                placeholder="1" 
              />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="flex items-center justify-between px-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400">Variações e Preços</label>
             <button onClick={() => setShowPresets(!showPresets)} className="text-[9px] font-black uppercase tracking-widest text-primary flex items-center gap-1 hover:text-primary-dark transition-colors">
               <span className="material-symbols-outlined text-sm">auto_awesome</span> Presets
             </button>
          </div>

          {showPresets && (
            <div className="grid grid-cols-2 gap-2 p-2 bg-neutral-50 dark:bg-black/20 rounded-xl animate-in fade-in zoom-in duration-200">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="p-3 text-[8px] font-black uppercase bg-white dark:bg-white/5 rounded-lg border border-neutral-100 dark:border-white/10 active:scale-95 transition-all">{p.name}</button>
              ))}
            </div>
          )}

          <div className="space-y-2.5">
            {variants.map((v, idx) => (
              <div key={v.id} className={`flex items-center gap-2 animate-in slide-in-from-left duration-200 ${!v.isActive ? 'opacity-50' : ''}`} style={{ animationDelay: `${idx * 40}ms` }}>
                <input 
                  value={v.name} 
                  onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} 
                  className={`flex-1 bg-neutral-50 dark:bg-black/20 p-2.5 rounded-lg text-xs font-black outline-none transition-all ${!v.isActive ? 'line-through' : ''}`} 
                  placeholder="Nome" 
                />

                <div className="relative w-24 shrink-0">
                  <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] font-black opacity-30">R$</span>
                  <input 
                    type="number" 
                    step="0.01"
                    value={v.price || ''} 
                    onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} 
                    className="w-full bg-neutral-50 dark:bg-black/20 p-2.5 pl-6 rounded-lg text-xs font-black outline-none border border-transparent focus:border-primary/30 transition-all" 
                    placeholder="0,00" 
                  />
                </div>

                <button 
                  onClick={() => toggleVariantStatus(v.id)} 
                  className={`relative w-8 h-5 rounded-full transition-all duration-300 outline-none shrink-0 shadow-inner ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}
                >
                  <div className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${v.isActive ? 'translate-x-3' : 'translate-x-0'}`} />
                </button>

                <button onClick={() => handleRemoveVariant(v.id)} className="w-8 h-8 flex items-center justify-center text-red-500 bg-red-50 dark:bg-red-900/10 rounded-lg active:scale-90 transition-all shrink-0">
                  <span className="material-symbols-outlined text-base">close</span>
                </button>
              </div>
            ))}
            <button onClick={() => setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }])} className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-40 hover:opacity-100 transition-all">+ Adicionar Nova Variação</button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t border-neutral-100 dark:border-white/10 z-50 flex gap-4">
        <button onClick={onCancel} className="flex-1 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] bg-neutral-100 dark:bg-white/5 active:scale-95 transition-all text-neutral-600 dark:text-neutral-300">Sair</button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving}
          className="flex-[2] py-5 bg-primary text-black rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-primary/30 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSaving ? 'Gravando...' : 'Confirmar'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  logoUrl?: string;
  canInstall?: boolean;
  onInstall?: () => void;
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  logoUrl, canInstall, onInstall, products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const [imgError, setImgError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const MIN_ORDER_VALUE = 200;
  const isMinOrderMet = total >= MIN_ORDER_VALUE;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isMinOrderMet) return;
    if (!isNameValid) {
      setShowNameError(true);
      const el = document.getElementById('checkout-form');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/sugestao-${Date.now()}.png`;
          const file = new File([blob], `sugestao.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart?.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  const isButtonDisabled = cart.length === 0 || isProcessing || !isNameValid || !isMinOrderMet;

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      {/* Botão de Instalação PWA */}
      {canInstall && (
        <div className="bg-primary/10 border-b border-primary/20 px-4 py-2 flex items-center justify-between animate-in slide-in-from-top duration-500">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-primary-dark">install_mobile</span>
            <span className="text-[10px] font-black uppercase tracking-widest">Instale o App na tela inicial</span>
          </div>
          <button onClick={onInstall} className="bg-primary text-black px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest active:scale-95 transition-all shadow-sm">Instalar</button>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {logoUrl && !imgError && (
            <div className="w-12 h-12 flex items-center justify-center">
               <img 
                 src={logoUrl} 
                 alt="Doce Mania" 
                 className="w-full h-full object-contain"
                 onError={() => setImgError(true)}
               />
            </div>
          )}
          <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania Atacado</h1>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="mb-6 px-2 text-center">
          <p className="text-[10px] font-black uppercase tracking-widest text-primary-dark">
            🔥 PREÇOS EXCLUSIVOS DE ATACADO! 🔥
          </p>
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em] mt-1.5">
            PEDIDO MÍNIMO PARA ENTREGA: R$ 200,00
          </p>
        </div>

        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;
            const unitsPerBox = product.units_per_box || 1;
            const isPackItem = unitsPerBox > 1;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <div className="flex justify-between items-start mb-0.5">
                    <h3 className="font-black text-xl leading-tight">{product.name}</h3>
                    {isPackItem && (
                      <span className="bg-primary/20 text-primary-dark text-[8px] font-black px-2 py-1 rounded-md uppercase tracking-widest">Caixa c/ {unitsPerBox} un</span>
                    )}
                  </div>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-6">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      return (
                        <div key={v.id} className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[10px] font-black text-neutral-400 uppercase tracking-widest">{v.name}</span>
                            <span className="font-black text-lg text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3">
                            {qty > 0 ? (
                              <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-full p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-full flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </div>
                            ) : (
                              <button 
                                onClick={() => addToCart(product, v.id)} 
                                className="bg-neutral-100 dark:bg-white/10 px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-all shadow-sm flex flex-col items-center"
                              >
                                <span>ADICIONAR</span>
                                {isPackItem && <span className="text-[7px] opacity-60 mt-0.5">({unitsPerBox} UNIDADES)</span>}
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - ATACADO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-4 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2 mb-4">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
              <div className="text-center mt-6 pt-4 border-t border-dashed opacity-40">
                <p className="text-[8px] uppercase font-bold tracking-widest">Aviso: Preços especiais de atacado.</p>
                <p className="text-[8px] uppercase font-bold tracking-widest">Pedido sujeito a disponibilidade.</p>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Seu Nome * (Obrigatório)</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); setShowNameError(false); }} 
                  className={`w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 transition-all ${showNameError ? 'border-red-500' : 'border-transparent focus:border-primary'}`} 
                  placeholder="Como devemos te chamar?" 
                />
                {!isNameValid && clientName.length > 0 && <p className="text-[9px] font-bold text-neutral-400 ml-1 italic">Mínimo de 3 caracteres...</p>}
                {showNameError && <p className="text-[9px] font-bold text-red-500 ml-1">Por favor, informe seu nome para continuar.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Forma de Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['Pix', 'Dinheiro'] as const).map(method => (
                    <button 
                      key={method}
                      onClick={() => setPaymentMethod(method)}
                      className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${paymentMethod === method ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10 opacity-60'}`}
                    >
                      {method}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmOrder}
                  disabled={isButtonDisabled}
                  className={`w-full py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed shadow-none' : 'bg-primary text-black shadow-primary/40'}`}
                >
                  {isProcessing ? 'PROCESSANDO...' : !isMinOrderMet ? `FALTAM R$ ${(MIN_ORDER_VALUE - total).toFixed(2)} PARA O MÍNIMO` : 'ENVIAR PEDIDO DE ATACADO'}
                </button>

                <div className="text-center px-4 space-y-2">
                  {!isMinOrderMet && (
                    <p className="text-[9px] font-black text-red-500 uppercase tracking-widest animate-pulse">
                      Atingir R$ 200,00 libera os preços de atacado
                    </p>
                  )}
                  <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest leading-relaxed">
                    * Preços especiais de revenda válidos para<br/>pedidos acima de R$ 200,00.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CatalogView;

export interface ProductVariant {
  id: string;
  name: string;
  price: number;
  isActive: boolean;
  units_per_box?: number; // Campo movido para o nível de variação
}

export interface VariationPreset {
  id: string;
  name: string;
  variants: ProductVariant[];
}

export interface Product {
  id: string;
  name: string;
  description: string;
  image: string;
  category: string;
  isActive: boolean;
  variants: ProductVariant[];
  order_index?: number;
}

export interface CartItem {
  productId: string;
  variantId: string;
  quantity: number;
  productName: string;
  variantName: string;
  price: number;
}

export type AppView = 'catalog' | 'admin' | 'add-product' | 'edit-product' | 'login' | 'edit-categories' | 'edit-variations';

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5554991107242');
  const [logoUrl, setLogoUrl] = useState<string>('https://vvywceybsdfyyuwvsqnq.supabase.co/storage/v1/object/public/product-images/logo.png');

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('catalog_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    const handler = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  useEffect(() => {
    localStorage.setItem('catalog_cart', JSON.stringify(cart));
  }, [cart]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*');

      if (prodError) throw prodError;

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price),
            units_per_box: v.units_per_box ?? 1
          }))
        }));

        const sorted = [...normalized].sort((a, b) => (a.order_index ?? 9999) - (b.order_index ?? 9999));
        setProducts(sorted);
      } else {
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        const logo = dbSettings.find(s => s.key === 'logo')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
        if (logo) setLogoUrl(logo);
      }
    } catch (err: any) {
      console.warn("Usando dados locais:", err.message);
      setProducts(INITIAL_PRODUCTS);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const maxOrder = products.length > 0 ? Math.max(...products.map(p => p.order_index ?? 0)) : 0;

      const payload = {
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        variants: product.variants.map((v: any) => ({
          id: v.id,
          name: v.name,
          price: v.price,
          is_active: v.isActive,
          units_per_box: v.units_per_box ?? 1
        })),
        is_active: product.isActive,
        order_index: product.order_index ?? (maxOrder + 1)
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      await fetchData(); 
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + err.message);
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const currentIndex = products.findIndex(p => p.id === id);
    if (currentIndex === -1) return;

    const targetIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = newProducts[currentIndex];
    const itemB = newProducts[targetIndex];

    const tempOrder = itemA.order_index ?? currentIndex;
    itemA.order_index = itemB.order_index ?? targetIndex;
    itemB.order_index = tempOrder;

    if (itemA.order_index === itemB.order_index) {
        if (direction === 'up') itemA.order_index--;
        else itemA.order_index++;
    }

    setProducts([...newProducts].sort((a, b) => (a.order_index ?? 9999) - (b.order_index ?? 9999)));

    try {
      await Promise.all([
        supabase.from('products').update({ order_index: itemA.order_index }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: itemB.order_index }).eq('id', itemB.id)
      ]);
    } catch (err) {
      console.error("Erro ao reordenar no banco:", err);
    }
  };

  const handleSendWhatsApp = (paymentMethod: string, receiptUrl?: string) => {
    if (cart.length === 0) return;

    const colDesc = 18;
    const colQty = 4;
    const colVal = 8;

    const header = "********************************\n" +
                   "*      CUPOM NÃO FISCAL        *\n" +
                   "********************************\n\n";

    const clientInfo = `👤 *Cliente:* ${clientName || 'Não identificado'}\n` +
                       `--------------------------------\n`;

    const tableHeader = "```" + 
                        "DESCRIÇÃO".padEnd(colDesc) + 
                        "QTD".padStart(colQty) + 
                        "VALOR".padStart(colVal) + "\n" +
                        "--------------------------------\n";

    const itemsText = cart.map(item => {
      const name = `${item.productName} (${item.variantName})`.substring(0, colDesc - 1).padEnd(colDesc);
      const qty = `${item.quantity}x`.padStart(colQty);
      const val = (item.price * item.quantity).toFixed(2).padStart(colVal);
      return `${name}${qty}${val}`;
    }).join('\n');

    const footerTable = "\n--------------------------------\n```";

    const totalValue = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const summary = `💰 *TOTAL:* R$ ${totalValue.toFixed(2)}\n` +
                    `💳 *PAGAMENTO:* ${paymentMethod}\n` +
                    `--------------------------------\n\n` +
                    `✅ *OBRIGADO PELA PREFERÊNCIA!*\n` +
                    `_Escaneie o QR Code e pague com PIX_`;

    let message = `${header}${clientInfo}${tableHeader}${itemsText}${footerTable}${summary}`;

    if (receiptUrl) {
      message += `\n\n🖼️ *VER RECIBO:* ${receiptUrl}`;
    }

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
    setCart([]); 
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark font-display">
      {isLoading ? (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-xs uppercase tracking-widest text-primary animate-pulse">Iniciando App...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              logoUrl={logoUrl}
              canInstall={!!deferredPrompt}
              onInstall={handleInstall}
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} 
              addToCart={(p, vId) => {
                const variant = p.variants.find(v => v.id === vId);
                if (!variant) return;

                const step = variant.units_per_box || 1;

                setCart(prev => {
                  const exists = prev.find(i => i.productId === p.id && i.variantId === vId);
                  if (exists) return prev.map(i => (i.productId === p.id && i.variantId === vId) ? {...i, quantity: i.quantity + step} : i);
                  return [...prev, { productId: p.id, variantId: vId, quantity: step, productName: p.name, variantName: variant.name, price: variant.price }];
                });
              }}
              removeFromCart={(pId, vId) => {
                const product = products.find(p => p.id === pId);
                const variant = product?.variants.find(v => v.id === vId);
                const step = variant?.units_per_box || 1;

                setCart(prev => prev.map(i => (i.productId === pId && i.variantId === vId) ? {...i, quantity: i.quantity - step} : i).filter(i => i.quantity > 0));
              }}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} 
              onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              logoUrl={logoUrl}
              setLogoUrl={async (url) => {
                setLogoUrl(url);
                await supabase.from('settings').upsert({ key: 'logo', value: url }, { onConflict: 'key' });
              }}
              products={products} whatsappNumber={whatsappNumber} 
              setWhatsappNumber={async (num) => {
                setWhatsappNumber(num);
                await supabase.from('settings').upsert({ key: 'whatsapp', value: num }, { onConflict: 'key' });
              }}
              storageReady={true}
              onToggleStatus={async (id) => {
                const p = products.find(x => x.id === id);
                if (p) {
                  const next = !p.isActive;
                  setProducts(prev => prev.map(x => x.id === id ? {...x, isActive: next} : x));
                  await supabase.from('products').update({ is_active: next }).eq('id', id);
                }
              }} 
              onToggleVariantStatus={async (pId, vId) => {
                const p = products.find(x => x.id === pId);
                if (p) {
                  const updated = p.variants.map(v => v.id === vId ? {...v, isActive: !v.isActive} : v);
                  setProducts(prev => prev.map(x => x.id === pId ? {...x, variants: updated} : x));
                  await supabase.from('products').update({ 
                    variants: updated.map(v => ({
                      id: v.id,
                      name: v.name,
                      price: v.price,
                      is_active: v.isActive,
                      units_per_box: v.units_per_box
                    })) 
                  }).eq('id', pId);
                }
              }}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} 
              onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={async (id) => {
                if (confirm("Excluir produto permanentemente?")) {
                  await supabase.from('products').delete().eq('id', id);
                  fetchData();
                }
              }}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} presets={presets} storageReady={true}
              productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} 
            setCategories={async (val: any) => {
              const next = typeof val === 'function' ? val(categories) : val;
              setCategories(next);
              await supabase.from('settings').upsert({ key: 'categories', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} 
            setPresets={async (val: any) => {
              const next = typeof val === 'function' ? val(presets) : val;
              setPresets(next);
              await supabase.from('settings').upsert({ key: 'presets', value: next }, { onConflict: 'key' });
            }} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  storageReady?: boolean | 'error';
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true, units_per_box: 1 }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({ 
        ...v, 
        price: Number(v.price),
        units_per_box: v.units_per_box ?? 1
      })));
      setShowLinkInput(!productToEdit.image || !productToEdit.image.includes('supabase'));
    } else {
      setShowLinkInput(true);
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    const srcMatch = raw.match(/src=["']([^"']+)["']/i);
    const plainUrlMatch = raw.match(/(https?:\/\/[^\s"'>]+)/i);

    if (srcMatch && srcMatch[1]) {
      raw = srcMatch[1];
    } else if (plainUrlMatch) {
      raw = plainUrlMatch[0];
    }
    setImage(raw);
  };

  const uploadFile = async (file: File) => {
    if (!file) return;
    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `item-${Date.now()}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      setImage(data.publicUrl);
      setShowLinkInput(false);
    } catch (error: any) {
      alert(`Erro no upload: ${error.message}`);
    } finally { setIsUploading(false); }
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    setVariants(preset.variants.map(v => ({ 
      ...v, 
      id: Math.random().toString(36).substr(2, 9), 
      isActive: true,
      units_per_box: v.units_per_box ?? 1
    })));
    setShowPresets(false);
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert("O produto deve ter pelo menos uma variação.");
      return;
    }
    if (confirm("Deseja realmente excluir esta variação?")) {
      setVariants(prev => prev.filter(x => x.id !== id));
    }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) {
      alert('Por favor, preencha o Nome do Produto e a Marca/Categoria.');
      return;
    }
    setIsSaving(true);
    try {
      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/400?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: variants.filter(v => v.name),
        order_index: productToEdit?.order_index
      });
    } catch (err) {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-44 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-neutral-100 dark:hover:bg-white/5 active:scale-95 transition-all">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h1 className="font-black text-[11px] uppercase tracking-[0.2em]">{productToEdit ? 'Editar Produto' : 'Cadastrar Produto'}</h1>
        <div className="w-10"></div>
      </div>

      <div className="p-4 space-y-4">
        <div className="bg-white dark:bg-white/5 p-3 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="aspect-square rounded-[1.5rem] bg-neutral-50 dark:bg-black/40 overflow-hidden flex items-center justify-center border-2 border-dashed border-neutral-200 dark:border-white/10 relative">
            {isUploading ? (
              <div className="flex flex-col items-center">
                <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="text-[8px] font-black uppercase mt-3 text-primary tracking-widest">Enviando...</p>
              </div>
            ) : image ? (
              <>
                <img src={image} className="w-full h-full object-contain p-2" onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Link+Invalido'} />
                <button onClick={() => setImage('')} className="absolute top-3 right-3 w-8 h-8 bg-red-500 text-white rounded-full shadow-lg flex items-center justify-center active:scale-90 transition-all z-10">
                  <span className="material-symbols-outlined text-lg">delete</span>
                </button>
              </>
            ) : (
              <div className="text-center opacity-30 flex flex-col items-center">
                <span className="material-symbols-outlined text-5xl mb-2">image</span>
                <p className="text-[9px] font-black uppercase tracking-widest">Nenhuma foto</p>
              </div>
            )}
          </div>

          <div className="flex gap-2">
            <button onClick={() => fileInputRef.current?.click()} className="flex-1 py-3 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-700 dark:text-emerald-400 rounded-xl flex items-center justify-center gap-1.5 text-[8px] font-black uppercase tracking-widest active:scale-95 transition-all border border-emerald-100/50">
              <span className="material-symbols-outlined text-base">upload</span> 
              Trocar Arquivo
            </button>
            <button onClick={() => setShowLinkInput(!showLinkInput)} className="flex-1 py-3 bg-neutral-100 dark:bg-white/5 text-neutral-500 dark:text-neutral-400 rounded-xl flex items-center justify-center gap-1.5 text-[8px] font-black uppercase tracking-widest active:scale-95 transition-all border border-neutral-200/50">
              <span className="material-symbols-outlined text-base">link</span> 
              Link Manual
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && uploadFile(e.target.files[0])} />
          </div>

          {showLinkInput && (
            <div className="animate-in slide-in-from-top-2 px-1">
              <input 
                value={image} 
                onChange={(e) => handleImageInput(e.target.value)} 
                placeholder="Cole o link ou tag HTML aqui..." 
                className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-[11px] font-medium outline-none border border-neutral-200 dark:border-white/10 shadow-inner"
              />
            </div>
          )}
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-1">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary transition-all" placeholder="Ex: Cheetos Mix" />
          </div>

          <div className="space-y-1.5">
            <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400 ml-1">Marca / Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-primary appearance-none transition-all">
              <option value="">Selecione...</option>
              {categories.filter(c => c !== 'Todas').map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-[2rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-4">
          <div className="flex items-center justify-between px-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-neutral-400">Variações e Preços</label>
             <button onClick={() => setShowPresets(!showPresets)} className="text-[9px] font-black uppercase tracking-widest text-primary flex items-center gap-1 hover:text-primary-dark transition-colors">
               <span className="material-symbols-outlined text-sm">auto_awesome</span> Presets
             </button>
          </div>

          {showPresets && (
            <div className="grid grid-cols-2 gap-2 p-2 bg-neutral-50 dark:bg-black/20 rounded-xl animate-in fade-in zoom-in duration-200">
              {presets.map(p => (
                <button key={p.id} onClick={() => handleApplyPreset(p)} className="p-3 text-[8px] font-black uppercase bg-white dark:bg-white/5 rounded-lg border border-neutral-100 dark:border-white/10 active:scale-95 transition-all">{p.name}</button>
              ))}
            </div>
          )}

          <div className="space-y-4">
            {variants.map((v, idx) => (
              <div key={v.id} className={`bg-neutral-50 dark:bg-black/10 p-3 rounded-2xl border border-neutral-100 dark:border-white/5 space-y-3 animate-in slide-in-from-left duration-200 ${!v.isActive ? 'opacity-50' : ''}`} style={{ animationDelay: `${idx * 40}ms` }}>
                <div className="flex items-center gap-2">
                  <input 
                    value={v.name} 
                    onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, name: e.target.value} : x))} 
                    className={`flex-1 bg-white dark:bg-black/40 p-2.5 rounded-lg text-xs font-black outline-none transition-all ${!v.isActive ? 'line-through' : ''}`} 
                    placeholder="Nome (ex: 300ml)" 
                  />
                  <button onClick={() => toggleVariantStatus(v.id)} className={`relative w-10 h-6 rounded-full transition-all duration-300 outline-none shrink-0 shadow-inner ${v.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}>
                    <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${v.isActive ? 'translate-x-4' : 'translate-x-0'}`} />
                  </button>
                  <button onClick={() => handleRemoveVariant(v.id)} className="w-8 h-8 flex items-center justify-center text-red-500 bg-red-50 dark:bg-red-900/10 rounded-lg active:scale-90 transition-all shrink-0">
                    <span className="material-symbols-outlined text-base">close</span>
                  </button>
                </div>

                <div className="flex gap-2">
                  <div className="flex-1 space-y-1">
                    <label className="text-[8px] font-black text-neutral-400 uppercase tracking-widest ml-1">Preço Un.</label>
                    <div className="relative">
                      <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] font-black opacity-30">R$</span>
                      <input 
                        type="number" 
                        step="0.01"
                        value={v.price || ''} 
                        onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, price: parseFloat(e.target.value) || 0} : x))} 
                        className="w-full bg-white dark:bg-black/40 p-2 pl-6 rounded-lg text-xs font-black outline-none border border-transparent focus:border-primary/30" 
                        placeholder="0,00" 
                      />
                    </div>
                  </div>
                  <div className="flex-1 space-y-1">
                    <label className="text-[8px] font-black text-neutral-400 uppercase tracking-widest ml-1">Qtd p/ Caixa</label>
                    <input 
                      type="number" 
                      min="1"
                      value={v.units_per_box || ''} 
                      onChange={(e) => setVariants(prev => prev.map(x => x.id === v.id ? {...x, units_per_box: Math.max(1, parseInt(e.target.value) || 1)} : x))} 
                      className="w-full bg-white dark:bg-black/40 p-2 rounded-lg text-xs font-black outline-none border border-transparent focus:border-primary/30 text-center" 
                      placeholder="1" 
                    />
                  </div>
                </div>
              </div>
            ))}
            <button onClick={() => setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true, units_per_box: 1 }])} className="w-full py-4 border-2 border-dashed border-neutral-200 dark:border-white/10 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-40 hover:opacity-100 transition-all">+ Adicionar Nova Variação</button>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-t border-neutral-100 dark:border-white/10 z-50 flex gap-4">
        <button onClick={onCancel} className="flex-1 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] bg-neutral-100 dark:bg-white/5 active:scale-95 transition-all text-neutral-600 dark:text-neutral-300">Sair</button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving}
          className="flex-[2] py-5 bg-primary text-black rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-primary/30 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSaving ? 'Gravando...' : 'Confirmar'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';
import { supabase } from '../supabase';

declare var html2canvas: any;

interface CatalogViewProps {
  logoUrl?: string;
  canInstall?: boolean;
  onInstall?: () => void;
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string, receiptUrl?: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  logoUrl, canInstall, onInstall, products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showNameError, setShowNameError] = useState(false);
  const [imgError, setImgError] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const MIN_ORDER_VALUE = 200;
  const isMinOrderMet = total >= MIN_ORDER_VALUE;

  const handleConfirmOrder = async () => {
    if (cart.length === 0) return;
    if (!isMinOrderMet) return;
    if (!isNameValid) {
      setShowNameError(true);
      const el = document.getElementById('checkout-form');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    setIsProcessing(true);
    setProcessingStatus('Enviando...');

    let receiptUrl = undefined;

    try {
      if (receiptRef.current) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const fileName = `receipts/sugestao-${Date.now()}.png`;
          const file = new File([blob], `sugestao.png`, { type: 'image/png' });

          try {
            const { error: uploadError } = await supabase.storage
              .from('product-images')
              .upload(fileName, file);

            if (!uploadError) {
              const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
              receiptUrl = data.publicUrl;
            }
          } catch (err) {}
        }
      }
    } catch (err) {} finally {
      onSendWhatsApp(paymentMethod, receiptUrl);
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const getQuantity = (pId: string, vId: string) => {
    return cart?.find(i => i.productId === pId && i.variantId === vId)?.quantity || 0;
  };

  const isButtonDisabled = cart.length === 0 || isProcessing || !isNameValid || !isMinOrderMet;

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto min-h-screen flex flex-col pb-40">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex flex-col items-center justify-center text-white text-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold text-sm uppercase tracking-widest">{processingStatus}</p>
        </div>
      )}

      {/* Botão de Instalação PWA */}
      {canInstall && (
        <div className="bg-primary/10 border-b border-primary/20 px-4 py-2 flex items-center justify-between animate-in slide-in-from-top duration-500">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-primary-dark">install_mobile</span>
            <span className="text-[10px] font-black uppercase tracking-widest">Instale o App na tela inicial</span>
          </div>
          <button onClick={onInstall} className="bg-primary text-black px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest active:scale-95 transition-all shadow-sm">Instalar</button>
        </div>
      )}

      <header className="sticky top-0 z-50 bg-white/95 dark:bg-background-dark/95 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {logoUrl && !imgError && (
            <div className="w-12 h-12 flex items-center justify-center">
               <img 
                 src={logoUrl} 
                 alt="Doce Mania" 
                 className="w-full h-full object-contain"
                 onError={() => setImgError(true)}
               />
            </div>
          )}
          <h1 className="font-black text-sm uppercase tracking-tight">Doce Mania Atacado</h1>
        </div>
        <button onClick={onOpenSettings} className="w-10 h-10 flex items-center justify-center rounded-full text-neutral-400 hover:bg-neutral-100 dark:hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">account_circle</span>
        </button>
      </header>

      <main className="px-4 pt-4">
        <div className="mb-6 px-2 text-center">
          <p className="text-[10px] font-black uppercase tracking-widest text-primary-dark">
            🔥 PREÇOS EXCLUSIVOS DE ATACADO! 🔥
          </p>
          <p className="text-[9px] font-bold text-neutral-400 uppercase tracking-[0.2em] mt-1.5">
            PEDIDO MÍNIMO PARA ENTREGA: R$ 200,00
          </p>
        </div>

        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`shrink-0 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'bg-neutral-100 dark:bg-white/5 opacity-60'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 gap-8 pt-4">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm overflow-hidden">
                <div className="w-full min-h-[320px] bg-neutral-50 dark:bg-black/20 flex items-center justify-center p-4">
                  <img 
                    src={product.image} 
                    className="max-w-full max-h-[400px] w-auto h-auto object-contain rounded-2xl" 
                    onError={(e) => e.currentTarget.src='https://picsum.photos/400/400?text=Sem+Foto'}
                    loading="lazy"
                  />
                </div>

                <div className="p-6">
                  <div className="flex justify-between items-start mb-0.5">
                    <h3 className="font-black text-xl leading-tight">{product.name}</h3>
                  </div>
                  <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.2em] mb-6">{product.category}</p>

                  <div className="space-y-3">
                    {activeVariants.map(v => {
                      const qty = getQuantity(product.id, v.id);
                      const unitsPerBox = v.units_per_box || 1;
                      const isPack = unitsPerBox > 1;

                      return (
                        <div key={v.id} className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-black/20 rounded-2xl border border-neutral-100 dark:border-white/5">
                          <div className="flex flex-col">
                            <span className="text-[10px] font-black text-neutral-400 uppercase tracking-widest flex items-center gap-1">
                              {v.name}
                              {isPack && <span className="bg-primary/20 text-primary-dark text-[7px] px-1.5 py-0.5 rounded-md">Caixa {unitsPerBox}un</span>}
                            </span>
                            <span className="font-black text-lg text-primary-dark">R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3">
                            {qty > 0 ? (
                              <div className="flex items-center gap-3 bg-white dark:bg-neutral-800 rounded-full p-1.5 shadow-sm border border-neutral-100 dark:border-white/5">
                                <button onClick={() => removeFromCart(product.id, v.id)} className="w-9 h-9 flex items-center justify-center text-neutral-400 hover:text-red-500 transition-colors"><span className="material-symbols-outlined text-lg">remove</span></button>
                                <span className="w-4 text-center text-sm font-black">{qty}</span>
                                <button onClick={() => addToCart(product, v.id)} className="w-9 h-9 bg-primary rounded-full flex items-center justify-center text-black active:scale-90 transition-transform"><span className="material-symbols-outlined text-lg font-bold">add</span></button>
                              </div>
                            ) : (
                              <button 
                                onClick={() => addToCart(product, v.id)} 
                                className="bg-neutral-100 dark:bg-white/10 px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest text-primary-dark active:scale-95 transition-all shadow-sm flex flex-col items-center min-w-[120px]"
                              >
                                <span>ADICIONAR</span>
                                {isPack && <span className="text-[7px] opacity-60 mt-0.5">(PACK {unitsPerBox}UN)</span>}
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div id="checkout-form" className="mt-16 space-y-6 pb-10">
            <div ref={receiptRef} className="p-8 bg-white text-black font-mono text-[11px] rounded-3xl border-t-[12px] border-primary shadow-2xl">
              <h3 className="text-center font-black text-sm uppercase mb-6 tracking-tighter">DOCE MANIA - ATACADO</h3>
              <div className="space-y-1 mb-6 border-b border-dashed pb-4">
                <p>CLIENTE: <span className="font-black">{clientName.toUpperCase() || '---'}</span></p>
                <p>PAGAMENTO: <span className="font-black">{paymentMethod.toUpperCase()}</span></p>
              </div>
              <div className="border-b border-dashed mb-6 pb-4 space-y-2">
                {cart.map(item => (
                  <div key={item.variantId} className="flex justify-between gap-4">
                    <span className="flex-1">{item.quantity}x {item.productName} ({item.variantName})</span>
                    <span className="font-black">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="flex justify-between font-black text-lg pt-2 mb-4">
                <span>TOTAL</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
              <div className="text-center mt-6 pt-4 border-t border-dashed opacity-40">
                <p className="text-[8px] uppercase font-bold tracking-widest">Aviso: Preços especiais de atacado.</p>
                <p className="text-[8px] uppercase font-bold tracking-widest">Pedido sujeito a disponibilidade.</p>
              </div>
            </div>

            <div className="bg-white dark:bg-white/5 p-8 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-sm space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Seu Nome * (Obrigatório)</label>
                <input 
                  value={clientName} 
                  onChange={(e) => { setClientName(e.target.value); setShowNameError(false); }} 
                  className={`w-full bg-neutral-50 dark:bg-black/20 p-4 rounded-2xl text-sm font-black outline-none border-2 transition-all ${showNameError ? 'border-red-500' : 'border-transparent focus:border-primary'}`} 
                  placeholder="Como devemos te chamar?" 
                />
                {!isNameValid && clientName.length > 0 && <p className="text-[9px] font-bold text-neutral-400 ml-1 italic">Mínimo de 3 caracteres...</p>}
                {showNameError && <p className="text-[9px] font-bold text-red-500 ml-1">Por favor, informe seu nome para continuar.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 ml-1">Forma de Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['Pix', 'Dinheiro'] as const).map(method => (
                    <button 
                      key={method}
                      onClick={() => setPaymentMethod(method)}
                      className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${paymentMethod === method ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-neutral-100 dark:bg-white/10 opacity-60'}`}
                    >
                      {method}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmOrder}
                  disabled={isButtonDisabled}
                  className={`w-full py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${isButtonDisabled ? 'bg-neutral-200 text-neutral-400 cursor-not-allowed shadow-none' : 'bg-primary text-black shadow-primary/40'}`}
                >
                  {isProcessing ? 'PROCESSANDO...' : !isMinOrderMet ? `FALTAM R$ ${(MIN_ORDER_VALUE - total).toFixed(2)} PARA O MÍNIMO` : 'ENVIAR PEDIDO DE ATACADO'}
                </button>

                <div className="text-center px-4 space-y-2">
                  {!isMinOrderMet && (
                    <p className="text-[9px] font-black text-red-500 uppercase tracking-widest animate-pulse">
                      Atingir R$ 200,00 libera os preços de atacado
                    </p>
                  )}
                  <p className="text-[9px] font-black text-neutral-400 uppercase tracking-widest leading-relaxed">
                    * Preços especiais de revenda válidos para<br/>pedidos acima de R$ 200,00.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default CatalogView;

import React, { useState, useRef } from 'react';
import { Product } from '../types';
import { supabase } from '../supabase';

interface AdminViewProps {
  logoUrl?: string;
  setLogoUrl: (url: string) => void;
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  storageReady: boolean | 'error';
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
  onReorderProduct: (id: string, direction: 'up' | 'down') => void;
  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  logoUrl,
  setLogoUrl,
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  onToggleStatus, 
  onToggleVariantStatus,
  onReorderProduct,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onBack, 
  onLogout 
}) => {
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [isUploadingLogo, setIsUploadingLogo] = useState(false);
  const [tempPhone, setTempPhone] = useState(whatsappNumber);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const handleSavePhone = () => {
    const cleaned = tempPhone.replace(/\D/g, '');
    if (cleaned.length < 10) return;
    setWhatsappNumber(cleaned);
    setIsEditingPhone(false);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploadingLogo(true);
    try {
      const fileName = `settings/logo-${Date.now()}.png`;
      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('product-images').getPublicUrl(fileName);
      setLogoUrl(data.publicUrl);
    } catch (err: any) {
      alert("Erro ao enviar logo: " + err.message);
    } finally {
      setIsUploadingLogo(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-white/90 dark:bg-background-dark/90 backdrop-blur-md border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5">
            <span className="material-symbols-outlined">arrow_back</span>
          </button>
          <h1 className="font-black text-sm uppercase tracking-widest">Painel Admin</h1>
        </div>
        <button onClick={onLogout} className="text-red-500 font-black text-[10px] uppercase tracking-[0.2em] px-4 py-2 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-xl transition-all">Sair</button>
      </div>

      <div className="p-4 space-y-6">
        {/* Gestão Rápida */}
        <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-neutral-100 dark:border-white/5 shadow-xl space-y-6">
          <div className="flex gap-3">
            <button onClick={onOpenCategories} className="flex-1 py-4 bg-neutral-100 dark:bg-white/10 rounded-2xl flex flex-col items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all group">
              <span className="material-symbols-outlined text-neutral-400 group-hover:text-primary transition-colors">category</span> 
              Marcas
            </button>
            <button onClick={onOpenVariations} className="flex-1 py-4 bg-neutral-100 dark:bg-white/10 rounded-2xl flex flex-col items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all group">
              <span className="material-symbols-outlined text-neutral-400 group-hover:text-primary transition-colors">list_alt</span> 
              Presets
            </button>
          </div>

          <div className="space-y-4 pt-2">
            <div className="flex items-center justify-between p-4 bg-neutral-50 dark:bg-black/20 rounded-3xl border border-neutral-100 dark:border-white/5">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center overflow-hidden border shadow-sm p-1">
                  {logoUrl ? (
                    <img src={logoUrl} className="w-full h-full object-contain" />
                  ) : (
                    <span className="material-symbols-outlined text-neutral-300">image</span>
                  )}
                </div>
